/* ERLY Noor Lab — syllabus models: PHYSICS (v18).
   JEE Main (NTA units) / JEE Advanced / NEET physics chapters and core undergraduate physics with no model before.
   Already served elsewhere and not repeated: projectiles, Newton's laws on a flat surface, collisions, springs, pendulums,
   rolling, pulleys (Atwood / massive pulley), orbits, circuits and nodal analysis, electric fields and point charges,
   magnetic field of wires and solenoids, Lorentz force, EM induction, waves / interference / Doppler / diffraction,
   ray optics (lenses, mirrors, prisms), gas laws and kinetic theory, radioactive decay.
   g = 9.8 m/s² throughout unless the student sets another value. */
(function () {
  'use strict';
  const L = window.ERLY_LAB; if (!L || !L.syl) return;
  const Y = L.syl, T = L.T, f3 = Y.f3, P = Y.p;
  const g0 = 9.8, R = 8.314462618, kB = 1.380649e-23, h = 6.62607015e-34, c0 = 2.99792458e8, e = 1.602176634e-19, me = 9.1093837015e-31, eps0 = 8.8541878128e-12, NA = 6.02214076e23;
  const rad = d => d * Math.PI / 180, deg = r => r * 180 / Math.PI;
  const K = { kin: T('Physics · Kinematics', 'فيزياء · الحركة'), lm: T('Physics · Laws of motion', 'فيزياء · قوانين الحركة'), wep: T('Physics · Work, energy and power', 'فيزياء · الشغل والطاقة'), grav: T('Physics · Gravitation', 'فيزياء · الجاذبية'), mat: T('Physics · Properties of solids and liquids', 'فيزياء · خواص المادة'), th: T('Physics · Thermodynamics', 'فيزياء · الديناميكا الحرارية'), osc: T('Physics · Oscillations', 'فيزياء · الاهتزازات'), es: T('Physics · Electrostatics', 'فيزياء · الكهرباء الساكنة'), ac: T('Physics · EMI and AC', 'فيزياء · التيار المتردد'), emw: T('Physics · EM waves and optics', 'فيزياء · الموجات الكهرومغناطيسية'), mod: T('Physics · Dual nature and atoms', 'فيزياء · الفيزياء الحديثة'), nuc: T('Physics · Nuclei', 'فيزياء · النواة'), dev: T('Physics · Electronic devices', 'فيزياء · الإلكترونيات'), adv: T('Physics · Undergraduate (modern)', 'فيزياء · جامعية'), exp: T('Physics · Experimental skills', 'فيزياء · المهارات العملية') };

  /* ---------- kinematics ---------- */
  Y.def({ id: 'kin1d', kind: K.kin, title: T('Motion in a straight line: x–t, v–t and a–t graphs', 'الحركة في خط مستقيم'), unit: 'JEE Main · Kinematics', probe: 'a car starts at 20 m/s and decelerates at 4 m/s²: show its velocity–time graph and the distance travelled in 8 s',
    rx: /\b(motion in a straight line|(uniform(ly)?|constant) accelerat\w*|equations? of (uniformly accelerated )?motion|suvat|v\s*=\s*u\s*\+\s*at|s\s*=\s*ut|velocity[- ]time graphs?|v-t graphs?|displacement[- ]time graphs?|x-t graphs?|position[- ]time graphs?|acceleration[- ]time graphs?|area under (a |the )?velocity|decelerat\w*)\b/i, not: /\bprojectile|thrown at an angle|circular\b/i, score: 0.94,
    p: [['u', T('initial velocity u', 'السرعة الابتدائية'), 'm/s', -30, 30, 0.5, 20, /(?:starts?|initial(?:ly)?|moving)\s*(?:at|with|velocity|speed)?\s*(?:of\s*)?(-?\d+(?:\.\d+)?)\s*m\/s/i], ['a', T('acceleration a', 'التسارع'), 'm/s²', -10, 10, 0.1, -4, /accelerat\w*\s*(?:of|at|is)?\s*(-?\d+(?:\.\d+)?)/i], ['t1', T('time interval', 'الزمن'), 's', 1, 20, 0.5, 8, /(?:in|for|after)\s*(\d+(?:\.\d+)?)\s*s(?:ec|econds?)?\b/i]],
    parse: t => { const m = String(t).match(/decelerat\w*\s*(?:of|at|is)?\s*(\d+(?:\.\d+)?)/i); return m ? { a: -m[1] } : {}; },
    sel: [['gr', T('graph', 'الرسم'), [['v', 'v–t', /velocity[- ]time|v-t/i], ['x', 'x–t', /displacement[- ]time|position[- ]time|x-t/i], ['a', 'a–t', /acceleration[- ]time|a-t/i]], 'v']],
    auto: true, view: S => { const fx = t => S.u * t + 0.5 * S.a * t * t, fv = t => S.u + S.a * t, vals = Array.from({ length: 41 }, (_, i) => (S.gr === 'x' ? fx : S.gr === 'v' ? fv : () => S.a)(S.t1 * i / 40)), lo = Math.min(0, ...vals), hi = Math.max(0, ...vals); return { x0: -0.3, x1: S.t1 * 1.05, y0: lo - (hi - lo) * 0.12 - 1, y1: hi + (hi - lo) * 0.15 + 1 }; }, labels: { x: 't (s)', y: '' },
    draw(p, S, c, H) { const fv = t => S.u + S.a * t, fx = t => S.u * t + 0.5 * S.a * t * t;
      if (S.gr === 'v') { H.shade(p, t => Math.max(0, fv(t)), null, 0, S.t1, 'rgba(37,99,235,.2)'); H.shade(p, t => Math.min(0, fv(t)), null, 0, S.t1, 'rgba(220,38,38,.2)'); H.curve(p, fv, 0, S.t1, c.pal[0], { w: 2.6 }); H.lab(p, 0.2, p.view.y1 * 0.9, T('shaded area = displacement (red counts negative)', 'المساحة = الإزاحة'), c.muted); }
      if (S.gr === 'x') H.curve(p, fx, 0, S.t1, c.pal[1], { w: 2.6 });
      if (S.gr === 'a') H.curve(p, () => S.a, 0, S.t1, c.pal[2], { w: 2.6 });
      const ts = S.a ? -S.u / S.a : -1; if (ts > 0 && ts < S.t1) p.dot(ts, S.gr === 'x' ? fx(ts) : S.gr === 'v' ? 0 : S.a, c.pal[3], T(`turns at t = ${f3(ts)} s`, 'يعكس الاتجاه')); },
    ro: S => { const k = kin(S); return [['v = u + at', f3(k.v) + ' m/s'], ['s = ut + ½at² (displacement)', f3(k.s) + ' m'], [T('distance travelled', 'المسافة'), f3(k.d) + ' m'], ['v² = u² + 2as', `${f3(k.v * k.v)} = ${f3(S.u * S.u + 2 * S.a * k.s)}`]]; },
    st: S => kin(S),
    intro: S => { const k = kin(S), ts = S.a ? -S.u / S.a : -1; return T(`With u = ${S.u} m/s and a = ${S.a} m/s², after ${S.t1} s the velocity is ${f3(k.v)} m/s and the displacement ${f3(k.s)} m.${ts > 0 && ts < S.t1 ? ` The body stops at t = ${f3(ts)} s and comes back, so the distance travelled (${f3(k.d)} m) is more than the displacement.` : ''} On the v–t graph the slope is the acceleration and the area is the displacement.`, 'الحركة بتسارع ثابت.'); },
    ex: () => P('v = u + at;  s = ut + ½at²;  v² = u² + 2as;  sₙ (in the nth second) = u + a(2n − 1)/2.  Slope of x–t = v, slope of v–t = a, area under v–t = displacement.') });
  function kin(S) { const v = S.u + S.a * S.t1, s = S.u * S.t1 + 0.5 * S.a * S.t1 * S.t1, ts = S.a ? -S.u / S.a : -1; let d; if (ts > 0 && ts < S.t1) { const s1 = S.u * ts + 0.5 * S.a * ts * ts; d = Math.abs(s1) + Math.abs(s - s1); } else d = Math.abs(s); return { v, s, d }; }

  Y.def({ id: 'riverboat', kind: K.kin, title: T('Relative velocity: crossing a river', 'السرعة النسبية: عبور النهر'), unit: 'JEE Main · Kinematics (relative velocity)', probe: 'a boat moves at 5 m/s in still water across a 100 m river flowing at 3 m/s: where should it head to cross straight, and how long does it take?',
    rx: /\b(river\s*-?\s*boat|cross(es|ing)? (a|the) river|swimmer (crosses|crossing|swims across)|relative velocity|rain\s*-?\s*man|drift of (the )?(boat|swimmer)|boat\b.*\briver|river\b.*\b(boat|swimmer))\b/i,
    p: [['vb', T('boat speed in still water', 'سرعة القارب'), 'm/s', 0.5, 10, 0.1, 5, /(\d+(?:\.\d+)?)\s*m\/s in still water|still water (?:at|of)\s*(\d+(?:\.\d+)?)/i], ['vr', T('river speed', 'سرعة النهر'), 'm/s', 0, 8, 0.1, 3, /(?:river|current|stream)\s*(?:\w+\s*){0,3}?(?:at|of|is)\s*(\d+(?:\.\d+)?)\s*m\/s|flowing at\s*(\d+(?:\.\d+)?)/i], ['w', T('river width', 'عرض النهر'), 'm', 10, 500, 5, 100, /(\d+(?:\.\d+)?)\s*m\s*(?:wide|river|broad)/i], ['th', T('heading upstream of straight across', 'زاوية التوجيه'), '°', -80, 80, 1, 0]],
    parse: t => (/\b(straight|directly|shortest path|zero drift|opposite point)\b/i.test(t) ? { th: -1 } : {}),
    init: (S, st, api) => { if (S.th === -1) { S.th = S.vr < S.vb ? +deg(Math.asin(S.vr / S.vb)).toFixed(1) : 0; if (api && api.sliders && api.sliders.th) api.sliders.th.set(S.th); } },
    equal: true, auto: true, view: S => ({ x0: -S.w * 0.4, x1: S.w * 1.4, y0: -S.w * 0.15, y1: S.w * 1.15 }), labels: { x: T('downstream (m)', 'مع التيار'), y: T('across (m)', 'عرضاً') },
    draw(p, S, c, H) { p.path([[-1e4, 0], [1e4, 0]], c.pal[5], { w: 2 }); p.path([[-1e4, S.w], [1e4, S.w]], c.pal[5], { w: 2 });
      for (let x = -S.w * 0.3; x < S.w * 1.4; x += S.w * 0.25) p.arrow(x, S.w * 0.5, x + S.w * 0.08, S.w * 0.5, c.muted, '', { w: 1 });
      const r = boat(S); if (r.t > 0) { p.path([[0, 0], [r.drift, S.w]], c.pal[0], { w: 2.6 }); p.dot(r.drift, S.w, c.pal[0], T(`lands ${f3(r.drift)} m downstream`, 'يصل')); }
      const k = S.w * 0.06; p.arrow(0, 0, -Math.sin(rad(S.th)) * S.vb * k, Math.cos(rad(S.th)) * S.vb * k, c.pal[1], T('heading (v boat)', 'الاتجاه')); p.arrow(0, 0, S.vr * k, 0, c.pal[3], T('river', 'النهر')); p.arrow(0, 0, (S.vr - S.vb * Math.sin(rad(S.th))) * k, S.vb * Math.cos(rad(S.th)) * k, c.pal[2], T('resultant', 'المحصلة'), { w: 3 }); },
    ro: S => { const r = boat(S); return [[T('time to cross t = w/(v_b cos θ)', 'زمن العبور'), f3(r.t) + ' s'], [T('drift = (v_r − v_b sin θ)·t', 'الانجراف'), f3(r.drift) + ' m'], [T('speed over ground', 'السرعة الفعلية'), f3(r.vg) + ' m/s'], [T('heading for zero drift', 'لصفر انجراف'), S.vr < S.vb ? f3(deg(Math.asin(S.vr / S.vb))) + T('° upstream', '° عكس التيار') : T('impossible (river faster than boat)', 'مستحيل')], [T('shortest time', 'أقصر زمن'), f3(S.w / S.vb) + T(' s (head straight across)', ' ث')]]; },
    st: S => boat(S),
    intro: S => { const r = boat(S); return T(`The boat’s velocity relative to the ground is its velocity relative to the water plus the river’s velocity (green = blue + red). Heading ${S.th}° upstream it takes ${f3(r.t)} s and lands ${f3(r.drift)} m downstream. To cross fastest, head straight across (t = w/v_b = ${f3(S.w / S.vb)} s); to land directly opposite, head upstream at sin θ = v_r/v_b.`, 'جمع السرعات.'); },
    ex: () => P('v⃗(boat, ground) = v⃗(boat, water) + v⃗(water, ground).  Across: v_b cos θ;  downstream: v_r − v_b sin θ.  Zero drift needs v_b > v_r; then t = w/√(v_b² − v_r²).') });
  function boat(S) { const ac = S.vb * Math.cos(rad(S.th)), dn = S.vr - S.vb * Math.sin(rad(S.th)), t = ac > 1e-9 ? S.w / ac : Infinity; return { t, drift: dn * t, vg: Math.hypot(ac, dn) }; }

  /* ---------- laws of motion ---------- */
  function incl(S) { const th = rad(S.th), W = S.m * g0, Nf = W * Math.cos(th), drive = S.F - W * Math.sin(th), fsMax = S.mus * Nf;
    if (Math.abs(drive) <= fsMax + 1e-12) return { a: 0, friction: -drive, N: Nf, moving: false, dir: 0 };
    const dir = Math.sign(drive), fk = S.muk * Nf; return { a: (drive - dir * fk) / S.m, friction: -dir * fk, N: Nf, moving: true, dir }; }
  Y.def({ id: 'incline', kind: K.lm, title: T('A block on an inclined plane with friction', 'جسم على مستوى مائل'), unit: 'JEE Main · Laws of motion (friction)', probe: 'a 4 kg block rests on a 30° incline with μs = 0.4 and μk = 0.3: does it slide, and with what acceleration?',
    rx: /\b(inclined? planes?|block on (a |an |the )?(slope|incline|ramp|wedge)|(on|down|up) (a |an |the )?(ramp|slope|incline)|angle of repose|slides? (down|up) (a |the )?(slope|incline|ramp)|rough incline|smooth incline|(on|down|up) (a |an |the )?(\d+(\.\d+)?\s*(°|-?degrees?)\s*)?(incline|slope|ramp)|incline (of|at|with))\b/i, not: /\b(roll\w*|cylinder|sphere|disc|ring|ball|hoop)\b/i, score: 0.95,
    p: [['m', T('mass', 'الكتلة'), 'kg', 0.5, 50, 0.5, 4, /(\d+(?:\.\d+)?)\s*kg/i], ['th', T('incline angle', 'زاوية الميل'), '°', 0, 80, 1, 30, /(\d+(?:\.\d+)?)\s*(?:°|degrees?|deg)/i], ['mus', 'μs', '', 0, 1.5, 0.01, 0.4, /μ\s*s\s*=\s*(\d*\.?\d+)|static (?:friction )?(?:coefficient )?(?:of )?(\d*\.?\d+)/i], ['muk', 'μk', '', 0, 1.5, 0.01, 0.3, /μ\s*k\s*=\s*(\d*\.?\d+)|kinetic (?:friction )?(?:coefficient )?(?:of )?(\d*\.?\d+)/i], ['F', T('push up the slope F', 'القوة لأعلى'), 'N', 0, 400, 1, 0, /(?:push|pull|force)\w*\s*(?:of)?\s*(\d+(?:\.\d+)?)\s*N/i]],
    parse: t => { const m = String(t).match(/μ\s*=\s*(\d*\.?\d+)/); return m ? { mus: +m[1], muk: +m[1] } : {}; },
    equal: true, view: { x0: -1, x1: 11, y0: -1, y1: 8 }, grid: false, labels: { x: '', y: '' },
    draw(p, S, c, H) { const th = rad(S.th), Lh = 10, top = [Lh, Lh * Math.tan(th)]; if (top[1] > 7.5) { top[0] = 7.5 / Math.tan(th); top[1] = 7.5; } H.poly(p, [[0, 0], top, [top[0], 0]], c.muted, { w: 2, fill: 'rgba(120,120,120,.12)' });
      const s = 0.55, ux = Math.cos(th), uy = Math.sin(th), nx = -uy, ny = ux, cx = top[0] * 0.55, cy = top[1] * 0.55; const bx = cx + nx * s, by = cy + ny * s;
      H.poly(p, [[cx - ux * s, cy - uy * s], [cx + ux * s, cy + uy * s], [cx + ux * s + nx * 2 * s, cy + uy * s + ny * 2 * s], [cx - ux * s + nx * 2 * s, cy - uy * s + ny * 2 * s]], c.pal[0], { w: 2, fill: 'rgba(37,99,235,.3)' });
      const r = incl(S), W = S.m * g0, k = 2.2 / Math.max(W, S.F, 1);
      p.arrow(bx, by, bx, by - W * k, c.pal[3], `mg = ${f3(W)} N`); p.arrow(bx, by, bx + nx * r.N * k, by + ny * r.N * k, c.pal[1], `N = ${f3(r.N)} N`);
      if (Math.abs(r.friction) > 1e-9) p.arrow(cx, cy, cx + ux * r.friction * k, cy + uy * r.friction * k, c.pal[2], `f = ${f3(Math.abs(r.friction))} N`);
      if (S.F) p.arrow(bx, by, bx + ux * S.F * k, by + uy * S.F * k, c.pal[4], `F = ${S.F} N`);
      H.lab(p, 0.6, 0.25, `${S.th}°`, c.ink); },
    ro: S => { const r = incl(S); return [[T('state', 'الحالة'), r.moving ? (r.dir < 0 ? T('slides down', 'ينزلق للأسفل') : T('moves up', 'يتحرك للأعلى')) : T('at rest (static friction holds it)', 'ساكن')], [T('acceleration', 'التسارع'), f3(r.a) + ' m/s²'], [T('friction', 'الاحتكاك'), `${f3(Math.abs(r.friction))} N ${r.moving ? T('(kinetic)', '(حركي)') : T('(static, ≤ μs N = ' + f3(S.mus * r.N) + ' N)', '')}`], ['N = mg cos θ', f3(r.N) + ' N'], [T('angle of repose tan⁻¹ μs', 'زاوية الاحتكاك'), f3(deg(Math.atan(S.mus))) + '°']]; },
    st: S => incl(S),
    intro: S => { const r = incl(S); return r.moving ? T(`The component of weight down the slope, mg sin θ = ${f3(S.m * g0 * Math.sin(rad(S.th)))} N${S.F ? `, together with your push of ${S.F} N,` : ''} beats the most static friction can give (μs N = ${f3(S.mus * r.N)} N), so the block moves. Kinetic friction μk N = ${f3(S.muk * r.N)} N opposes the motion, leaving a = ${f3(Math.abs(r.a))} m/s² ${r.dir < 0 ? 'down' : 'up'} the slope.`, 'ينزلق.') : T(`Static friction adjusts to exactly ${f3(Math.abs(r.friction))} N and holds the block, because that is less than its limit μs N = ${f3(S.mus * r.N)} N. Steepen the slope past the angle of repose (${f3(deg(Math.atan(S.mus)))}°) and it starts to slide.`, 'ساكن.'); },
    ex: () => P('Along the slope: F − mg sin θ ∓ f = ma;  perpendicular: N = mg cos θ.  Static friction: f ≤ μs N (only as much as needed);  kinetic: f = μk N.  Sliding down freely: a = g(sin θ − μk cos θ).') });

  function bank(S) { const th = rad(S.th), r = S.r, mu = S.mu, den1 = Math.cos(th) - mu * Math.sin(th), num2 = Math.sin(th) - mu * Math.cos(th); const vmax = den1 > 0 ? Math.sqrt(r * g0 * (Math.sin(th) + mu * Math.cos(th)) / den1) : Infinity, vmin = num2 > 0 ? Math.sqrt(r * g0 * num2 / (Math.cos(th) + mu * Math.sin(th))) : 0, vopt = Math.sqrt(r * g0 * Math.tan(th)); return { vmax, vmin, vopt, ac: S.v * S.v / r }; }
  Y.def({ id: 'banking', kind: K.lm, title: T('Circular motion and banked roads', 'الحركة الدائرية والطرق المائلة'), unit: 'JEE Main · Laws of motion (circular motion)', probe: 'what is the maximum speed of a car on a curve of radius 50 m banked at 15° with friction coefficient 0.3?',
    rx: /\b(bank(ing|ed) (of )?(roads?|curves?|tracks?|turns?)|banking angle|car (on|taking|rounding|going round) a (curve|turn|bend)|maximum (safe )?speed (on|round|around|for) (a |the )?(curve|turn|bend)|uniform circular motion|centripetal (force|acceleration)|skid(ding)? (on|round) a (curve|bend))\b/i, not: /\b(vertical circle|charged|magnetic|orbit|satellite|planet)\b/i, score: 0.95,
    p: [['r', T('radius of the curve', 'نصف القطر'), 'm', 5, 500, 1, 50, /radius\s*(?:of)?\s*(\d+(?:\.\d+)?)\s*m/i], ['th', T('banking angle', 'زاوية الميل'), '°', 0, 60, 0.5, 15, /bank\w*\s*(?:at|of|angle)?\s*(\d+(?:\.\d+)?)\s*(?:°|deg)/i], ['mu', T('friction coefficient μ', 'معامل الاحتكاك'), '', 0, 1.2, 0.01, 0.3, /(?:friction|μ)\s*(?:coefficient)?\s*(?:of|=|is)?\s*(\d*\.\d+)/i], ['v', T('car speed', 'سرعة السيارة'), 'm/s', 0, 60, 0.5, 15]],
    equal: true, view: { x0: -6, x1: 6, y0: -1, y1: 6 }, grid: false, labels: { x: '', y: '' },
    draw(p, S, c, H) { const th = rad(S.th), b = bank(S); p.path([[-5 * Math.cos(th), -5 * Math.sin(th) + 2], [5 * Math.cos(th), 5 * Math.sin(th) + 2]], c.muted, { w: 4 }); const cx = 0, cy = 2.5;
      H.poly(p, [[-0.6 * Math.cos(th), 2 - 0.6 * Math.sin(th)], [0.6 * Math.cos(th), 2 + 0.6 * Math.sin(th)], [0.6 * Math.cos(th) - 0.5 * Math.sin(th), 2 + 0.6 * Math.sin(th) + 0.5 * Math.cos(th)], [-0.6 * Math.cos(th) - 0.5 * Math.sin(th), 2 - 0.6 * Math.sin(th) + 0.5 * Math.cos(th)]], c.pal[0], { w: 2, fill: 'rgba(37,99,235,.3)' });
      p.arrow(cx, cy, cx, cy - 2, c.pal[3], 'mg'); p.arrow(cx, cy, cx - 2.2 * Math.sin(th), cy + 2.2 * Math.cos(th), c.pal[1], 'N'); p.arrow(cx + 2.4, cy, cx + 2.4 - Math.min(3, b.ac / g0 * 2), cy, c.pal[2], T('needed: mv²/r toward centre', 'المطلوب'), { w: 2 });
      H.lab(p, -5.8, 5.6, T('← centre of the curve', '← مركز المنحنى'), c.muted); },
    ro: S => { const b = bank(S); const ok = S.v <= b.vmax + 1e-9 && S.v >= b.vmin - 1e-9; return [[T('ideal speed (no friction) √(rg tan θ)', 'السرعة المثالية'), f3(b.vopt) + ' m/s'], ['v_max', isFinite(b.vmax) ? f3(b.vmax) + ' m/s' : T('no limit (μ ≥ cot θ)', 'لا حد')], ['v_min', f3(b.vmin) + ' m/s'], [T('centripetal acceleration v²/r', 'التسارع المركزي'), f3(b.ac) + ' m/s²'], [T(`at ${S.v} m/s`, `عند ${S.v}`), ok ? T('safe', 'آمن') : S.v > b.vmax ? T('skids outward', 'تنزلق للخارج') : T('slides inward', 'تنزلق للداخل')]]; },
    st: S => bank(S),
    intro: S => { const b = bank(S); return T(`Going round a curve needs a net force mv²/r toward the centre. On a road banked at ${S.th}° part of the normal force supplies it; friction can help either way. Without friction the one comfortable speed is √(rg tan θ) = ${f3(b.vopt)} m/s; with μ = ${S.mu} the car is safe between ${f3(b.vmin)} and ${isFinite(b.vmax) ? f3(b.vmax) : '∞'} m/s.`, 'القوة المركزية.'); },
    ex: () => P('v_max = √[rg (sin θ + μ cos θ)/(cos θ − μ sin θ)] = √[rg (μ + tan θ)/(1 − μ tan θ)];  flat road: v_max = √(μrg);  ideal banking: tan θ = v²/(rg).') });

  function vcirc(S) { const u = S.u, Rr = S.R, th = rad(S.th), v2 = u * u - 2 * g0 * Rr * (1 - Math.cos(th)), Tn = S.m * (v2 / Rr + g0 * Math.cos(th)); // θ measured from the bottom
    let slack = null; for (let a = 0; a <= Math.PI + 1e-9; a += Math.PI / 3600) { const vv = u * u - 2 * g0 * Rr * (1 - Math.cos(a)); if (S.m * (vv / Rr + g0 * Math.cos(a)) < 0 || vv < 0) { slack = a; break; } }
    return { v: v2 >= 0 ? Math.sqrt(v2) : null, T: Tn, complete: u >= Math.sqrt(5 * g0 * Rr) - 1e-9, umin: Math.sqrt(5 * g0 * Rr), slackDeg: slack == null ? null : deg(slack), Ttop: S.m * ((u * u - 4 * g0 * Rr) / Rr - g0), Tbot: S.m * (u * u / Rr + g0) }; }
  Y.def({ id: 'vcircle', kind: K.lm, title: T('Motion in a vertical circle', 'الحركة في دائرة رأسية'), unit: 'JEE Main · Work, energy and power / circular motion', probe: 'a 0.5 kg stone on a 1 m string is whirled in a vertical circle: what speed at the bottom lets it just complete the circle?',
    rx: /\b(vertical circle|loop[- ]the[- ]loop|complete the (circle|loop)|minimum (speed|velocity) at the (top|bottom|lowest|highest)|tension at the (top|bottom|lowest|highest)|(stone|ball|bob|bucket)\b.*\b(whirled|swung|string)\b.*\bvertical)\b/i, score: 0.96,
    p: [['m', T('mass', 'الكتلة'), 'kg', 0.1, 5, 0.1, 0.5, /(\d+(?:\.\d+)?)\s*kg/i], ['R', T('radius (string length)', 'نصف القطر'), 'm', 0.2, 5, 0.1, 1, /(\d+(?:\.\d+)?)\s*m\s*(?:long |length )?(?:string|rope|cord|radius)/i], ['u', T('speed at the bottom', 'السرعة عند الأسفل'), 'm/s', 0, 20, 0.05, 7], ['th', T('position from the bottom', 'الموقع'), '°', 0, 180, 1, 120]],
    equal: true, auto: true, view: S => ({ x0: -S.R * 1.8, x1: S.R * 1.8, y0: -S.R * 1.5, y1: S.R * 1.5 }), grid: false, labels: { x: '', y: '' },
    draw(p, S, c, H) { const r = vcirc(S); H.circle(p, 0, 0, S.R, c.muted, { w: 1.4, dash: [5, 4] }); if (r.slackDeg != null) { const a = rad(r.slackDeg); p.dot(S.R * Math.sin(a), -S.R * Math.cos(a), c.pal[3], T(`string goes slack (${f3(r.slackDeg)}°)`, 'ترتخي')); }
      const a = rad(S.th), x = S.R * Math.sin(a), y = -S.R * Math.cos(a); p.path([[0, 0], [x, y]], c.ink, { w: 1.6 }); p.dot(0, 0, c.ink, ''); p.dot(x, y, c.pal[0], '', { r: 8 });
      if (r.v != null) { const k = S.R * 0.12; p.arrow(x, y, x + Math.cos(a) * r.v * k / 3, y + Math.sin(a) * r.v * k / 3, c.pal[2], `v = ${f3(r.v)} m/s`); } p.arrow(x, y, x, y - S.R * 0.4, c.pal[3], 'mg');
      if (r.T > 0) p.arrow(x, y, x - Math.sin(a) * S.R * 0.4, y + Math.cos(a) * S.R * 0.4, c.pal[1], `T = ${f3(r.T)} N`); },
    ro: S => { const r = vcirc(S); return [[T('minimum speed at the bottom √(5gR)', 'الحد الأدنى'), f3(r.umin) + ' m/s'], [T('completes the circle?', 'يكمل الدائرة؟'), r.complete ? T('yes', 'نعم') : T('no', 'لا')], [T('tension at the bottom', 'الشد عند الأسفل'), f3(r.Tbot) + ' N'], [T('tension at the top', 'الشد عند الأعلى'), r.complete ? f3(r.Ttop) + ' N' : '—'], [T('speed / tension here', 'هنا'), r.v != null ? `${f3(r.v)} m/s / ${f3(r.T)} N` : T('not reached', 'لا يصل')]]; },
    st: S => vcirc(S),
    intro: S => { const r = vcirc(S); return r.complete ? T(`At ${S.u} m/s at the bottom the stone keeps the string taut all the way round: at the top it still has v² ≥ gR. The tension is greatest at the bottom (${f3(r.Tbot)} N) because there it must hold up the weight and provide the centripetal force.`, 'يكمل الدائرة.') : T(`${S.u} m/s is less than √(5gR) = ${f3(r.umin)} m/s, so the string goes slack at ${f3(r.slackDeg)}° from the bottom and the stone leaves the circle as a projectile.`, 'لا يكمل.'); },
    ex: () => P('Energy: v² = u² − 2gR(1 − cos θ) (θ from the bottom).  Radial: T − mg cos θ = mv²/R ⇒ T = m(v²/R + g cos θ).  Top: T_top = m(v_top²/R − g) ≥ 0 ⇒ v_top ≥ √(gR), u ≥ √(5gR).  T_bottom − T_top = 6mg.') });

  /* ---------- work, energy, power ---------- */
  const TRACK = x => 6 * Math.exp(-((x - 1) ** 2) / 2) + 3.2 * Math.exp(-((x - 6) ** 2) / 1.6) + 0.6;
  Y.def({ id: 'coaster', kind: K.wep, title: T('Conservation of mechanical energy (roller coaster)', 'حفظ الطاقة الميكانيكية'), unit: 'JEE Main · Work, energy and power', probe: 'show kinetic and potential energy changing as a roller coaster car goes down a hill and up the next',
    rx: /\b(conservation of (mechanical )?energy|roller ?coaster|potential (and|&) kinetic energy|kinetic (and|&) potential energy|energy (bar )?charts?|work[- ]energy theorem|mechanical energy|energy transformation)\b/i,
    p: [['m', T('mass', 'الكتلة'), 'kg', 1, 1000, 1, 500], ['x', T('position along the track', 'الموقع'), 'm', 0, 9, 0.01, 3.2], ['loss', T('energy lost to friction per metre', 'الفقد لكل متر'), 'J/m', 0, 2000, 10, 0]],
    view: { x0: -0.5, x1: 9.5, y0: -0.5, y1: 9 }, labels: { x: 'x (m)', y: T('height (m)', 'الارتفاع') },
    draw(p, S, c, H) { H.shade(p, TRACK, null, 0, 9, 'rgba(120,120,120,.12)'); H.curve(p, TRACK, 0, 9, c.ink, { w: 2.4 }); const E = en(S), y = TRACK(S.x);
      p.dot(S.x, y + 0.2, E.ok ? c.pal[0] : c.muted, '', { r: 8 }); if (!E.ok) H.lab(p, S.x, y + 0.9, T('the car cannot get here', 'لا تصل'), c.pal[3], { align: 'center' });
      const tot = E.E0, bx = 8.2, k = 6 / tot; [[E.ok ? E.PE : 0, 'PE', c.pal[1]], [E.ok ? E.KE : 0, 'KE', c.pal[2]], [E.ok ? E.lost : 0, T('lost', 'مفقود'), c.pal[3]]].forEach(([v, l, col], i) => { const x = bx + i * 0.45; p.path([[x, 2], [x, 2 + v * k]], col, { w: 10 }); H.lab(p, x, 1.6, l, col, { align: 'center' }); }); },
    ro: S => { const E = en(S); return [[T('height here', 'الارتفاع'), f3(TRACK(S.x)) + ' m'], ['PE = mgh', E.ok ? f3(E.PE) + ' J' : '—'], ['KE = E₀ − PE − losses', E.ok ? f3(E.KE) + ' J' : '—'], [T('speed', 'السرعة'), E.ok ? f3(Math.sqrt(2 * E.KE / S.m)) + ' m/s' : '—'], [T('total at the start', 'الطاقة الكلية'), f3(E.E0) + ' J']]; },
    st: S => { const E = en(S); return { PE: E.PE, KE: E.KE, speed: E.ok ? Math.sqrt(2 * E.KE / S.m) : null, reachable: E.ok }; },
    intro: () => T('The car starts at rest at the first peak. As it falls, potential energy mgh turns into kinetic energy; climbing turns it back. Without friction PE + KE stays the same everywhere, so the speed at any point depends only on how far below the start it is. Add friction and some energy is lost along the way.', 'تتحول الطاقة.'),
    ex: () => P('E = ½mv² + mgh = constant (no friction);  v = √(2g(h₀ − h));  with friction: W_friction = −ΔE_mech;  work–energy theorem: W_net = ΔKE.') });
  function en(S) { const h0 = TRACK(1), E0 = S.m * g0 * h0, dist = (() => { let s = 0; const n = 400, a = 1, b = S.x, lo = Math.min(a, b), hi = Math.max(a, b); for (let i = 0; i < n; i++) { const x0 = lo + (hi - lo) * i / n, x1 = lo + (hi - lo) * (i + 1) / n; s += Math.hypot(x1 - x0, TRACK(x1) - TRACK(x0)); } return s; })(), lost = S.loss * dist, PE = S.m * g0 * TRACK(S.x), KE = E0 - PE - lost; let ok = KE >= -1e-9; if (ok && S.x > 1) { for (let x = 1; x < S.x; x += 0.01) if (E0 - S.m * g0 * TRACK(x) - S.loss * Math.abs(x - 1) < -1e-6) { ok = false; break; } } return { E0, PE, KE: Math.max(0, KE), lost, ok }; }

  Y.def({ id: 'com', kind: K.lm, title: T('Centre of mass of a system of particles', 'مركز الكتلة'), unit: 'JEE Main · System of particles and rotational motion', probe: 'find the centre of mass of masses 2 kg at (0,0), 3 kg at (4,0) and 5 kg at (1,3)',
    rx: /\b(cent(re|er) of (mass|gravity)|\bcom\b of|centroid of masses|system of particles)\b/i, score: 0.95,
    p: [['m1', 'm₁', 'kg', 0, 10, 0.5, 2], ['x1', 'x₁', 'm', -5, 5, 0.1, 0], ['y1', 'y₁', 'm', -5, 5, 0.1, 0], ['m2', 'm₂', 'kg', 0, 10, 0.5, 3], ['x2', 'x₂', 'm', -5, 5, 0.1, 4], ['y2', 'y₂', 'm', -5, 5, 0.1, 0], ['m3', 'm₃', 'kg', 0, 10, 0.5, 5], ['x3', 'x₃', 'm', -5, 5, 0.1, 1], ['y3', 'y₃', 'm', -5, 5, 0.1, 3]],
    parse: t => { const ms = [...String(t).matchAll(/(\d+(?:\.\d+)?)\s*kg\s*(?:at|placed at|located at)?\s*\(\s*(-?[\d.]+)\s*,\s*(-?[\d.]+)\s*\)/gi)], o = {}; ms.slice(0, 3).forEach((m, i) => { o['m' + (i + 1)] = +m[1]; o['x' + (i + 1)] = +m[2]; o['y' + (i + 1)] = +m[3]; }); return o; },
    equal: true, view: { x0: -6, x1: 6, y0: -5, y1: 6 },
    draw(p, S, c) { const r = cm(S); [1, 2, 3].forEach(i => { if (S['m' + i] > 0) { p.dot(S['x' + i], S['y' + i], c.pal[i - 1], `${S['m' + i]} kg`, { r: 4 + 2 * Math.sqrt(S['m' + i]) }); p.path([[S['x' + i], S['y' + i]], [r.x, r.y]], c.muted, { w: 1, dash: [3, 4] }); } }); p.dot(r.x, r.y, c.ink, `COM (${f3(r.x)}, ${f3(r.y)})`, { r: 6, ring: true }); },
    ro: S => { const r = cm(S); return [['M = Σm', f3(r.M) + ' kg'], ['x_cm = Σmx/M', f3(r.x) + ' m'], ['y_cm = Σmy/M', f3(r.y) + ' m']]; },
    st: S => cm(S),
    intro: S => { const r = cm(S); return T(`The centre of mass is the mass-weighted average position: (${f3(r.x)}, ${f3(r.y)}) m. It lies closest to the heaviest mass. Make one mass much larger and the COM moves toward it.`, 'المتوسط المرجح.'); },
    ex: () => P('r_cm = Σmᵢrᵢ / Σmᵢ;  a system moves as if all external force acts on the total mass at the COM: F_ext = M a_cm.  With no external force, the COM keeps its velocity.') });
  function cm(S) { const M = S.m1 + S.m2 + S.m3; return M ? { M, x: (S.m1 * S.x1 + S.m2 * S.x2 + S.m3 * S.x3) / M, y: (S.m1 * S.y1 + S.m2 * S.y2 + S.m3 * S.y3) / M } : { M: 0, x: NaN, y: NaN }; }

  /* ---------- gravitation ---------- */
  const GM = 3.986004418e14, RE = 6.371e6;
  Y.def({ id: 'gravfield', kind: K.grav, title: T('Gravity of the Earth: g, potential, orbits and escape', 'جاذبية الأرض'), unit: 'JEE Main · Gravitation', probe: 'how does g change with height and depth, and what are the orbital and escape speeds at 400 km?',
    rx: /\b(acceleration due to gravity (with|at|varies|inside|below|above|change)|variation of g|g (inside|below the surface|at (a )?(depth|height|altitude))|escape (velocity|speed)|orbital (velocity|speed)|geostationary|geosynchronous|gravitational (potential( energy)?|field strength|field of the earth)|weight (inside|at the centre of) the earth|satellite (speed|period|at a height)|time period of a satellite|g\b.*\b(with )?(height|depth|altitude))\b/i, score: 0.97,
    p: [['hk', T('height above the surface (negative = depth)', 'الارتفاع (سالب = عمق)'), 'km', -6371, 40000, 1, 400, /(\d+(?:\.\d+)?)\s*km/i]],
    parse: t => (/\bdepth\b/i.test(t) ? (() => { const m = String(t).match(/(\d+(?:\.\d+)?)\s*km/i); return m ? { hk: -m[1] } : {}; })() : /geostationary/i.test(t) ? { hk: 35786 } : {}),
    view: { x0: 0, x1: 7, y0: 0, y1: 11 }, labels: { x: 'r / R_E', y: 'g (m/s²)' },
    draw(p, S, c, H) { const gr = x => (x < 1 ? GM / RE ** 2 * x : GM / (RE * x) ** 2); H.curve(p, gr, 0, 7, c.pal[0], { w: 2.6 }); p.path([[1, 0], [1, 11]], c.muted, { w: 1, dash: [4, 4] }); H.lab(p, 1.05, 10.4, T('surface', 'السطح'), c.muted);
      const x = 1 + S.hk * 1e3 / RE; p.dot(Math.min(7, x), gr(x), c.pal[3], `g = ${f3(gr(x))}`); H.lab(p, 2.2, 10.4, T('g ∝ r inside, g ∝ 1/r² outside', 'داخل وخارج'), c.ink); },
    ro: S => { const r = gv(S); return [['r', f3(r.r / 1e3) + ' km'], ['g', f3(r.g) + ' m/s²'], [T('gravitational potential', 'الجهد'), f3(r.V) + ' J/kg'], ...(S.hk >= 0 ? [[T('orbital speed √(GM/r)', 'سرعة المدار'), f3(r.vo / 1e3) + ' km/s'], [T('orbital period', 'الدورة'), f3(r.Tp / 3600) + ' h'], [T('escape speed √(2GM/r)', 'سرعة الإفلات'), f3(r.ve / 1e3) + ' km/s']] : [])]; },
    st: S => gv(S),
    intro: S => { const r = gv(S); return S.hk >= 0 ? T(`At ${S.hk} km up, g = ${f3(r.g)} m/s² (it falls as 1/r²). A satellite there circles at √(GM/r) = ${f3(r.vo / 1e3)} km/s, once every ${f3(r.Tp / 3600)} h; to escape completely it would need √2 times that, ${f3(r.ve / 1e3)} km/s.`, 'خارج الأرض.') : T(`${f3(-S.hk)} km below the surface (uniform Earth model), only the mass inside your radius pulls on you, so g falls linearly to zero at the centre: g = g₀(1 − d/R) = ${f3(r.g)} m/s².`, 'داخل الأرض.'); },
    ex: () => P('g(h) = GM/(R + h)² ≈ g₀(1 − 2h/R) for h ≪ R;  g(d) = g₀(1 − d/R);  V = −GM/r outside;  v_orbit = √(GM/r), T = 2π√(r³/GM), v_escape = √(2GM/r) = 11.2 km/s from the surface.'), assume: T('Earth as a uniform, non-rotating sphere (R = 6371 km, GM = 3.986×10¹⁴ m³/s²).', 'أرض منتظمة.') });
  function gv(S) { const r = RE + S.hk * 1e3; const g = r < RE ? GM / RE ** 2 * r / RE : GM / (r * r); const V = r < RE ? -GM / (2 * RE ** 3) * (3 * RE * RE - r * r) : -GM / r; return { r, g, V, vo: Math.sqrt(GM / r), Tp: 2 * Math.PI * Math.sqrt(r ** 3 / GM), ve: Math.sqrt(2 * GM / r) }; }

  /* ---------- properties of solids and liquids ---------- */
  const MATS = { steel: [T('mild steel', 'فولاذ'), 200e9, 250e6, 400e6], copper: [T('copper', 'نحاس'), 117e9, 70e6, 220e6], alu: [T('aluminium alloy 6061', 'ألومنيوم'), 69e9, 276e6, 310e6] };
  Y.def({ id: 'stressstrain', kind: K.mat, title: T('Stress–strain curve and Young’s modulus', 'منحنى الإجهاد والانفعال'), unit: 'JEE Main · Properties of solids and liquids', probe: 'a 2 m steel wire of cross-section 1 mm² carries 100 N: how much does it stretch? show the stress–strain curve',
    rx: /\b(stress[- ]strain|young'?s modulus|elastic limit|yield (point|strength|stress)|ultimate tensile|breaking stress|elongation of (a |the )?wire|extension of (a |the )?wire|modulus of elasticity|hooke'?s law\b.*\bwire|wire\b.*\bstretch\w*)\b/i, score: 0.95,
    sel: [['mat', T('material', 'المادة'), [['steel', T('mild steel', 'فولاذ'), /steel/i], ['copper', T('copper', 'نحاس'), /copper/i], ['alu', T('aluminium', 'ألومنيوم'), /alumin/i]], 'steel']],
    p: [['F', T('load F', 'الحمل'), 'N', 0, 400, 1, 100, /(\d+(?:\.\d+)?)\s*N\b/i], ['Lw', T('wire length', 'الطول'), 'm', 0.1, 10, 0.1, 2, /(\d+(?:\.\d+)?)\s*m\s*(?:long|steel|copper|wire)/i], ['A', T('cross-section', 'المقطع'), 'mm²', 0.1, 10, 0.1, 1, /(\d+(?:\.\d+)?)\s*mm(?:²|\^?2)/i]],
    auto: true, view: S => ({ x0: 0, x1: 0.06, y0: 0, y1: MATS[S.mat][3] / 1e6 * 1.2 }), labels: { x: T('strain', 'الانفعال'), y: T('stress (MPa)', 'الإجهاد') },
    draw(p, S, c, H) { const [, E, Y0, U] = MATS[S.mat], ey = Y0 / E, curve = x => (x <= ey ? E * x : x < 0.04 ? Y0 + (U - Y0) * Math.sin(Math.PI / 2 * (x - ey) / (0.04 - ey)) : U - (U - Y0) * 0.6 * ((x - 0.04) / 0.015) ** 2) / 1e6;
      H.curve(p, curve, 0, 0.055, c.pal[0], { w: 2.6 }, 500); p.dot(ey, Y0 / 1e6, c.pal[3], T('yield', 'الخضوع')); p.dot(0.04, U / 1e6, c.pal[1], T('ultimate', 'القصوى')); p.dot(0.055, curve(0.055), c.ink, T('fracture', 'الكسر'));
      const st = S.F / (S.A * 1e-6), sn = st / E; if (st <= Y0) p.dot(sn, st / 1e6, c.pal[2], T('your load', 'حملك'), { r: 6 }); },
    ro: S => { const [, E, Y0] = MATS[S.mat], st = S.F / (S.A * 1e-6), sn = st / E; return [['stress σ = F/A', f3(st / 1e6) + ' MPa'], ['strain = σ/Y', f3(sn)], [T('extension ΔL = FL/(AY)', 'الاستطالة'), f3(sn * S.Lw * 1e3) + ' mm'], ['Y', f3(E / 1e9) + ' GPa'], [T('within the elastic region?', 'ضمن المرونة؟'), st <= Y0 ? T('yes', 'نعم') : T('no — beyond yield, Hooke’s law no longer applies', 'لا')], [T('elastic energy ½FΔL', 'الطاقة'), st <= Y0 ? f3(0.5 * S.F * sn * S.Lw) + ' J' : '—']]; },
    st: S => { const [, E, Y0] = MATS[S.mat], st = S.F / (S.A * 1e-6), sn = st / E; return { stress: st, strain: sn, extension: sn * S.Lw, elastic: st <= Y0 }; },
    intro: S => { const [, E] = MATS[S.mat], st = S.F / (S.A * 1e-6); return T(`In the straight part of the curve stress is proportional to strain (Hooke’s law) and the slope is Young’s modulus, ${f3(E / 1e9)} GPa for ${MATS[S.mat][0]}. Your ${S.F} N on ${S.A} mm² is a stress of ${f3(st / 1e6)} MPa, so the ${S.Lw} m wire stretches by ΔL = FL/(AY) = ${f3(st / E * S.Lw * 1e3)} mm.`, 'قانون هوك.'); },
    ex: () => P('Y = (F/A)/(ΔL/L);  ΔL = FL/(AY);  elastic energy per volume = ½ σ ε;  beyond the yield point the deformation is partly permanent.'), assume: T('Typical handbook values (E, yield, ultimate); the shape beyond yield is schematic — real curves depend on the alloy and heat treatment.', 'قيم نموذجية.') });

  Y.def({ id: 'torricelli', kind: K.mat, title: T('Efflux: water jet from a hole in a tank (Torricelli)', 'قانون تورشيلي'), unit: 'JEE Main · Properties of solids and liquids (fluids)', probe: 'water in a 2 m tall tank flows from a hole: at what depth does the jet reach farthest?',
    rx: /\b(torricelli|efflux|hole (in|at the side of|near the bottom of) (a |the )?(tank|container|vessel|bucket)|water (jet|stream|spurts?) (from|out of) a hole|range of (a |the )?(water )?jet|leaking tank|flows? (out )?(from|through) a hole|hole\b.*\btank|tank\b.*\bhole)\b/i, score: 0.96,
    p: [['H', T('water height', 'ارتفاع الماء'), 'm', 0.5, 10, 0.1, 2, /(\d+(?:\.\d+)?)\s*m\s*(?:tall|high|deep)/i], ['d', T('depth of the hole below the surface', 'عمق الثقب'), 'm', 0.01, 10, 0.01, 0.6]],
    equal: true, auto: true, view: S => ({ x0: -1, x1: S.H * 2.4, y0: -0.2, y1: S.H * 1.25 }), grid: false, labels: { x: 'x (m)', y: 'y (m)' },
    draw(p, S, c, H) { const d = Math.min(S.d, S.H), yh = S.H - d; H.poly(p, [[-0.8, 0], [0, 0], [0, S.H * 1.1], [-0.8, S.H * 1.1]], c.ink, { w: 2 }); p.path([[-0.8, 0], [0, 0], [0, S.H], [-0.8, S.H]], c.pal[5], { w: 0.5, close: true, fill: 'rgba(14,165,233,.3)' }); p.path([[-1, 0], [1e3, 0]], c.muted, { w: 2 });
      const v = Math.sqrt(2 * g0 * d), t = Math.sqrt(2 * yh / g0), Rr = v * t; H.curve(p, x => yh - g0 * x * x / (2 * v * v), 0, Rr, c.pal[5], { w: 3 }); p.dot(Rr, 0, c.pal[3], `R = ${f3(Rr)} m`); p.dot(0, yh, c.ink, T('hole', 'الثقب'), { r: 3 });
      const best = S.H / 2; p.path([[0, best], [S.H, 0]], c.muted, { w: 0.8, dash: [2, 4] }); },
    ro: S => { const d = Math.min(S.d, S.H), v = Math.sqrt(2 * g0 * d), Rr = 2 * Math.sqrt(d * (S.H - d)); return [[T('efflux speed v = √(2gh)', 'سرعة الخروج'), f3(v) + ' m/s'], [T('range R = 2√(h(H − h))', 'المدى'), f3(Rr) + ' m'], [T('best depth for maximum range', 'العمق الأمثل'), f3(S.H / 2) + ' m'], [T('maximum range', 'أقصى مدى'), f3(S.H) + ' m']]; },
    st: S => { const d = Math.min(S.d, S.H); return { v: Math.sqrt(2 * g0 * d), range: 2 * Math.sqrt(d * (S.H - d)) }; },
    intro: S => T(`Water leaves a hole ${f3(S.d)} m below the surface at v = √(2gh) — the speed of a stone dropped that far. It then falls the remaining ${f3(S.H - S.d)} m as a projectile, landing R = 2√(h(H − h)) away. The range is greatest, equal to H, for a hole exactly halfway down; holes at depths h and H − h reach the same spot.`, 'تورشيلي.'),
    ex: () => P('Bernoulli between the surface and the hole: P₀ + ρgH = P₀ + ½ρv² + ρg(H − h) ⇒ v = √(2gh) (large tank).  Fall time t = √(2(H − h)/g), so R = v t = 2√(h(H − h)).'), assume: T('Wide tank (the surface barely moves), no viscosity, small hole.', 'خزان واسع.') });

  Y.def({ id: 'venturi', kind: K.mat, title: T('Bernoulli’s principle in a narrowing pipe (venturi)', 'مبدأ برنولي'), unit: 'JEE Main · Properties of solids and liquids (fluids)', probe: 'water flows at 2 m/s in a pipe of area 10 cm² that narrows to 4 cm²: find the speed and pressure drop',
    rx: /\b(bernoulli'?s?|venturi|continuity equation|equation of continuity|flow (through|in) a (narrow|constricted|tapering) pipe|pressure (drops|difference) .*pipe|streamline flow|aerofoil lift|why (do )?planes? fly|pipe\b.*\bnarrows?|narrow(s|ing|er)? (pipe|section|part)|constriction)\b/i, score: 0.95,
    p: [['A1', T('wide area A₁', 'المساحة A₁'), 'cm²', 1, 100, 0.5, 10], ['A2', T('narrow area A₂', 'المساحة A₂'), 'cm²', 0.5, 100, 0.5, 4], ['v1', T('speed in the wide part', 'السرعة v₁'), 'm/s', 0.1, 20, 0.1, 2, /(\d+(?:\.\d+)?)\s*m\/s/i], ['rho', T('fluid density', 'الكثافة'), 'kg/m³', 1, 13600, 1, 1000]],
    parse: t => { const a = [...String(t).matchAll(/(\d+(?:\.\d+)?)\s*cm(?:²|\^?2)/gi)]; return a.length >= 2 ? { A1: +a[0][1], A2: +a[1][1] } : {}; },
    view: { x0: 0, x1: 10, y0: -4, y1: 5 }, grid: false, labels: { x: '', y: '' },
    draw(p, S, c, H) { const r1 = Math.sqrt(S.A1) * 0.35, r2 = Math.sqrt(S.A2) * 0.35, rad = x => (x < 3 ? r1 : x > 7 ? r1 : x < 4 ? r1 + (r2 - r1) * (x - 3) : x > 6 ? r2 + (r1 - r2) * (x - 6) : r2);
      H.curve(p, rad, 0, 10, c.ink, { w: 2.4 }); H.curve(p, x => -rad(x), 0, 10, c.ink, { w: 2.4 }); for (let k = -2; k <= 2; k++) H.curve(p, x => rad(x) * k / 2.6, 0, 10, c.pal[5], { w: 1, dash: [6, 5] });
      const v2 = S.v1 * S.A1 / S.A2, dP = 0.5 * S.rho * (v2 * v2 - S.v1 * S.v1); p.arrow(1, 0, 1 + S.v1 * 0.25, 0, c.pal[0], `v₁ = ${f3(S.v1)}`); p.arrow(4.6, 0, 4.6 + Math.min(4, v2 * 0.25), 0, c.pal[0], `v₂ = ${f3(v2)}`);
      const hk = Math.min(2.5, 1.5 * Math.abs(dP) / Math.max(1, 0.5 * S.rho * v2 * v2)); p.path([[1.5, r1], [1.5, r1 + 1.6]], c.pal[1], { w: 6 }); p.path([[5, r2], [5, r2 + 1.6 - hk]], c.pal[1], { w: 6 }); H.lab(p, 1.6, r1 + 1.9, T('higher pressure', 'ضغط أعلى'), c.pal[1]); H.lab(p, 5.1, r2 + 1.9 - hk, T('lower pressure', 'ضغط أقل'), c.pal[1]); },
    ro: S => { const v2 = S.v1 * S.A1 / S.A2, dP = 0.5 * S.rho * (v2 * v2 - S.v1 * S.v1); return [[T('A₁v₁ = A₂v₂ ⇒ v₂', 'السرعة v₂'), f3(v2) + ' m/s'], ['P₁ − P₂ = ½ρ(v₂² − v₁²)', f3(dP) + ' Pa'], [T('volume flow rate', 'معدل التدفق'), f3(S.A1 * 1e-4 * S.v1 * 1000) + ' L/s']]; },
    st: S => { const v2 = S.v1 * S.A1 / S.A2; return { v2, dP: 0.5 * S.rho * (v2 * v2 - S.v1 * S.v1), Q: S.A1 * 1e-4 * S.v1 }; },
    intro: S => T(`The same volume per second passes every section (A₁v₁ = A₂v₂), so the fluid speeds up to ${f3(S.v1 * S.A1 / S.A2)} m/s in the narrow part. Bernoulli: where it moves faster its pressure is lower, by ½ρ(v₂² − v₁²) = ${f3(0.5 * S.rho * ((S.v1 * S.A1 / S.A2) ** 2 - S.v1 ** 2))} Pa — shown by the lower tube.`, 'برنولي.'),
    ex: () => P('P + ½ρv² + ρgh = constant along a streamline (steady, incompressible, non-viscous flow);  A₁v₁ = A₂v₂ (continuity).') });

  Y.def({ id: 'stokes', kind: K.mat, title: T('Viscosity and terminal velocity (Stokes’ law)', 'اللزوجة والسرعة الحدية'), unit: 'JEE Main · Properties of solids and liquids (viscosity)', probe: 'a 2 mm steel ball falls through glycerine: what is its terminal velocity and how quickly does it reach it?',
    rx: /\b(terminal (velocity|speed)|stokes'?s? law|viscosity|viscous (drag|force)|coefficient of viscosity|(ball|sphere|drop)\b.*\bfall\w* (through|in) (oil|glycerine|glycerol|honey|a (liquid|fluid)|water))\b/i, not: /\bskydiv|parachut/i, score: 0.95,
    p: [['r', T('ball radius', 'نصف القطر'), 'mm', 0.1, 10, 0.1, 1, /(\d+(?:\.\d+)?)\s*mm\s*(?:radius)/i], ['rho', T('ball density', 'كثافة الكرة'), 'kg/m³', 1000, 20000, 10, 7800], ['sig', T('fluid density', 'كثافة السائل'), 'kg/m³', 700, 13600, 10, 1260], ['eta', T('viscosity η', 'اللزوجة'), 'Pa·s', 0.001, 2, 0.001, 1.41]],
    parse: t => { const o = {}; const d = String(t).match(/(\d+(?:\.\d+)?)\s*mm\s*(?:diameter|steel|ball|sphere)/i); if (d) o.r = +d[1] / 2; if (/water/i.test(t)) { o.sig = 1000; o.eta = 0.001; } if (/castor oil/i.test(t)) { o.sig = 961; o.eta = 0.985; } return o; },
    ode: { y0: () => [0], f: (t, y, S) => { const r = S.r / 1e3; return [g0 * (1 - S.sig / S.rho) - 9 * S.eta / (2 * r * r * S.rho) * y[0]]; }, T: S => 5 * (2 * (S.r / 1e3) ** 2 * S.rho / (9 * S.eta)), names: ['v (m/s)'], tlabel: 't (s)' },
    view: { x0: -1, x1: 1, y0: -10, y1: 1 }, equal: false, grid: false, labels: { x: '', y: '' },
    draw(p, S, c, H, st) { p.path([[-0.6, 0.5], [-0.6, -9.5], [0.6, -9.5], [0.6, 0.5]], c.ink, { w: 2 }); p.path([[-0.6, 0], [0.6, 0], [0.6, -9.5], [-0.6, -9.5]], c.pal[3], { w: 0.5, close: true, fill: 'rgba(217,119,6,.15)' });
      const vt = vterm(S), T1 = 5 * tau(S), y = -9 * Math.min(1, (st.tt || 0) / T1); p.dot(0, y, c.ink, '', { r: 7 }); H.lab(p, 0.65, y, `v = ${f3((st.y || [0])[0])} m/s`, c.pal[0]); H.lab(p, -0.95, 0.8, T(`terminal v = ${f3(vt)} m/s`, 'السرعة الحدية'), c.pal[2]); },
    ro: S => [[T('terminal velocity 2r²(ρ − σ)g/(9η)', 'السرعة الحدية'), f3(vterm(S)) + ' m/s'], [T('time constant τ', 'الثابت الزمني'), f3(tau(S)) + ' s'], [T('Reynolds number (check Stokes applies)', 'عدد رينولدز'), f3(S.sig * vterm(S) * 2 * S.r / 1e3 / S.eta)]],
    st: S => ({ vt: vterm(S), tau: tau(S), Re: S.sig * vterm(S) * 2 * S.r / 1e3 / S.eta }),
    intro: S => T(`The ball speeds up until the viscous drag 6πηrv plus buoyancy balances its weight; then it falls steadily at the terminal velocity ${f3(vterm(S))} m/s. It gets there exponentially, with time constant τ = ${f3(tau(S))} s (graph).${S.sig * vterm(S) * 2 * S.r / 1e3 / S.eta > 1 ? ' Note the Reynolds number is above 1, so Stokes’ law overestimates the speed here.' : ''}`, 'السرعة الحدية.'),
    ex: () => P('Drag F = 6πηrv (Stokes, low Reynolds number);  at terminal velocity: (4/3)πr³(ρ − σ)g = 6πηr v_t ⇒ v_t = 2r²(ρ − σ)g/(9η);  v(t) = v_t(1 − e^{−t/τ}), τ = 2r²ρ/(9η).') });
  const vterm = S => 2 * (S.r / 1e3) ** 2 * (S.rho - S.sig) * g0 / (9 * S.eta), tau = S => 2 * (S.r / 1e3) ** 2 * S.rho / (9 * S.eta);

  Y.def({ id: 'capillary', kind: K.mat, title: T('Surface tension and capillary rise', 'التوتر السطحي والخاصية الشعرية'), unit: 'JEE Main · Properties of solids and liquids (surface tension)', probe: 'how high does water rise in a glass capillary of radius 0.5 mm, and why does mercury go down?',
    rx: /\b(capillar(y|ity|ies)|capillary (rise|action|tube)|surface tension|angle of contact|contact angle|meniscus|excess pressure (inside|in) a (drop|bubble))\b/i, score: 0.95,
    sel: [['liq', T('liquid', 'السائل'), [['water', T('water in clean glass', 'ماء'), /water/i], ['hg', T('mercury in glass', 'زئبق'), /mercury/i], ['eth', T('ethanol', 'إيثانول'), /alcohol|ethanol/i]], 'water']],
    p: [['r', T('tube radius', 'نصف قطر الأنبوب'), 'mm', 0.05, 3, 0.01, 0.5, /radius\s*(?:of)?\s*(\d*\.?\d+)\s*mm/i]],
    view: { x0: -6, x1: 6, y0: -6, y1: 8 }, grid: false, labels: { x: '', y: '' },
    draw(p, S, c, H) { const [Ts, th, rho] = LIQ[S.liq], hh = 2 * Ts * Math.cos(rad(th)) / (S.r / 1e3 * rho * g0) * 100; // cm
      p.path([[-6, 0], [6, 0], [6, -6], [-6, -6]], c.pal[5], { w: 0.5, close: true, fill: S.liq === 'hg' ? 'rgba(160,160,170,.5)' : 'rgba(14,165,233,.3)' }); const w = Math.max(0.15, S.r * 0.6), top = Math.max(-5.5, Math.min(7.5, hh));
      p.path([[-w, -5], [-w, 7.8]], c.ink, { w: 2 }); p.path([[w, -5], [w, 7.8]], c.ink, { w: 2 }); p.path([[-w, -5], [w, -5], [w, top], [-w, top]], c.pal[5], { w: 0.5, close: true, fill: S.liq === 'hg' ? 'rgba(160,160,170,.8)' : 'rgba(14,165,233,.5)' });
      H.curve(p, x => top + (S.liq === 'hg' ? 1 : -1) * 0.3 * (1 - (x / w) ** 2) * -1, -w, w, c.ink, { w: 1.6 }); H.lab(p, w + 0.3, top, `h = ${f3(hh)} cm`, c.pal[3]); },
    ro: S => { const [Ts, th, rho] = LIQ[S.liq], hh = 2 * Ts * Math.cos(rad(th)) / (S.r / 1e3 * rho * g0); return [['h = 2T cos θ/(rρg)', f3(hh * 100) + ' cm'], [T('surface tension T', 'التوتر السطحي'), Ts + ' N/m'], [T('contact angle θ', 'زاوية التماس'), th + '°'], [T('meniscus', 'الهلال'), th < 90 ? T('concave — liquid rises', 'مقعر — يرتفع') : T('convex — liquid is depressed', 'محدب — ينخفض')]]; },
    st: S => { const [Ts, th, rho] = LIQ[S.liq]; return { h: 2 * Ts * Math.cos(rad(th)) / (S.r / 1e3 * rho * g0) }; },
    intro: S => T(`${S.liq === 'hg' ? 'Mercury does not wet glass (contact angle ≈ 140°), so its meniscus is convex and it is pushed down.' : 'Water wets clean glass (θ ≈ 0°): surface tension pulls the edge up the wall and lifts a column until its weight balances the pull, 2πrT cos θ = πr²hρg.'} Narrower tubes give bigger effects, because h ∝ 1/r.`, 'الخاصية الشعرية.'),
    ex: () => P('h = 2T cos θ/(rρg) (Jurin’s law);  excess pressure inside a drop: 2T/r;  inside a soap bubble (two surfaces): 4T/r.'), assume: T('Values near 20 °C: water T = 0.0728 N/m, θ ≈ 0°; mercury T = 0.485 N/m, θ ≈ 140°; ethanol T = 0.0223 N/m, θ ≈ 0°.', 'قيم عند 20 °C.') });
  const LIQ = { water: [0.0728, 0, 998], hg: [0.485, 140, 13534], eth: [0.0223, 0, 789] };

  /* ---------- thermal physics and thermodynamics ---------- */
  Y.def({ id: 'cooling', kind: K.th, title: T('Newton’s law of cooling', 'قانون نيوتن للتبريد'), unit: 'JEE Main · Thermal properties of matter', probe: 'tea at 90 °C cools in a 25 °C room to 70 °C in 5 minutes: when will it reach 50 °C?',
    rx: /\b(newton'?s law of cooling|cooling curve|rate of cooling|cools? (down )?from \d+|(tea|coffee|body|liquid)\b.*\bcool\w*|time of death)\b/i, score: 0.95,
    p: [['T0', T('starting temperature', 'درجة البدء'), '°C', 0, 200, 1, 90, /(?:at|from)\s*(\d+(?:\.\d+)?)\s*°?\s*C/i], ['Ts', T('surroundings', 'المحيط'), '°C', -20, 60, 1, 25, /(?:room|surroundings?|air|environment)\s*(?:at|of|is)?\s*(\d+(?:\.\d+)?)\s*°?\s*C|(\d+(?:\.\d+)?)\s*°?\s*C\s*room/i], ['k', T('cooling constant k', 'ثابت التبريد'), '1/min', 0.005, 0.5, 0.001, 0.07], ['Tt', T('target temperature', 'الهدف'), '°C', -20, 200, 1, 50]],
    parse: t => { const m = String(t).match(/(\d+(?:\.\d+)?)\s*°?\s*C\b[^.]*?\bto\s*(\d+(?:\.\d+)?)\s*°?\s*C\s*in\s*(\d+(?:\.\d+)?)\s*min/i), o = {}; if (m) { const T0 = +m[1], T1 = +m[2], tm = +m[3], Ts = (String(t).match(/(\d+(?:\.\d+)?)\s*°?\s*C\s*room|room\s*(?:at|of)?\s*(\d+(?:\.\d+)?)/i) || []); const ts = Ts[1] || Ts[2]; if (ts) { const k = Math.log((T0 - +ts) / (T1 - +ts)) / tm; if (isFinite(k) && k > 0) o.k = +k.toFixed(4); } } const q = String(t).match(/reach\s*(\d+(?:\.\d+)?)\s*°?\s*C/i); if (q) o.Tt = +q[1]; return o; },
    ode: { y0: S => [S.T0], f: (t, y, S) => [-S.k * (y[0] - S.Ts)], T: S => Math.max(10, 4 / S.k), names: ['T (°C)'], tlabel: 't (min)' },
    view: { x0: -1, x1: 1, y0: -1, y1: 1 }, grid: false, labels: { x: '', y: '' },
    draw(p, S, c, H, st) { const Tn = (st.y || [S.T0])[0], f = Math.max(0, Math.min(1, (Tn - S.Ts) / Math.max(1, S.T0 - S.Ts))); H.circle(p, 0, -0.1, 0.55, c.ink, { w: 2, fill: `rgba(${Math.round(80 + 175 * f)},${Math.round(120 - 60 * f)},${Math.round(230 - 200 * f)},.6)` }); H.lab(p, 0, -0.85, `${f3(Tn)} °C`, c.ink, { align: 'center' }); H.lab(p, 0, 0.7, `t = ${f3(st.tt || 0)} min`, c.muted, { align: 'center' }); },
    ro: S => { const tt = S.Tt > S.Ts && S.Tt < S.T0 ? Math.log((S.T0 - S.Ts) / (S.Tt - S.Ts)) / S.k : null; return [['T(t) = Tₛ + (T₀ − Tₛ)e^{−kt}', ''], [T(`time to reach ${S.Tt} °C`, 'الزمن للوصول'), tt != null ? f3(tt) + ' min' : T('never (target outside the range)', 'لا يصل')], [T('half-difference time ln2/k', 'زمن نصف الفرق'), f3(Math.LN2 / S.k) + ' min']]; },
    st: S => ({ tTarget: S.Tt > S.Ts && S.Tt < S.T0 ? Math.log((S.T0 - S.Ts) / (S.Tt - S.Ts)) / S.k : null, halfTime: Math.LN2 / S.k, k: S.k }),
    intro: S => T(`The rate of cooling is proportional to how much hotter the body is than its surroundings, so the temperature difference decays exponentially: every ln2/k = ${f3(Math.LN2 / S.k)} min the gap to ${S.Ts} °C halves. It cools fast at first and ever more slowly near room temperature.`, 'التبريد الأسي.'),
    ex: () => P('dT/dt = −k(T − Tₛ) ⇒ T = Tₛ + (T₀ − Tₛ)e^{−kt};  t = (1/k) ln[(T₀ − Tₛ)/(T − Tₛ)].  JEE often uses the average form: (T₁ − T₂)/t = k[(T₁ + T₂)/2 − Tₛ].'), assume: T('Small temperature differences (convection-dominated); k depends on the object and its surface.', 'فروق صغيرة.') });

  function cyc(S) { const n = 1, g = S.gam === 'mono' ? 5 / 3 : 7 / 5, Cv = R / (g - 1), Pk = (T, V) => n * R * T / V; // V in litres → P in kPa
    if (S.cycle === 'carnot') { const V1 = 1, V2 = V1 * S.ratio, V3 = V2 * (S.Th / S.Tc) ** (1 / (g - 1)), V4 = V1 * V3 / V2; const W = n * R * (S.Th - S.Tc) * Math.log(V2 / V1), Qin = n * R * S.Th * Math.log(V2 / V1); return { g, pts: [[V1, V2, 'iso', S.Th], [V2, V3, 'adi', S.Th, V2], [V3, V4, 'iso', S.Tc], [V4, V1, 'adi', S.Tc, V4]], W, Qin, eta: W / Qin, etaFormula: 1 - S.Tc / S.Th, V: [V1, V2, V3, V4], Pk }; }
    if (S.cycle === 'otto') { const V1 = S.ratio, V2 = 1, T1 = S.Tc, T2 = T1 * S.ratio ** (g - 1), T3 = Math.max(T2 + 1, S.Th), T4 = T3 * S.ratio ** (1 - g); const Qin = n * Cv * (T3 - T2), Qout = n * Cv * (T4 - T1); return { g, pts: [[V1, V2, 'adi', T1, V1], [V2, V2, 'v', T2, T3], [V2, V1, 'adi', T3, V2], [V1, V1, 'v', T4, T1]], W: Qin - Qout, Qin, eta: 1 - Qout / Qin, etaFormula: 1 - S.ratio ** (1 - g), V: [V1, V2], Pk, T: [T1, T2, T3, T4] }; }
    const V1 = 1, V2 = S.ratio, Wi = n * R * S.Th * Math.log(V2 / V1), T2a = S.Th * (V1 / V2) ** (g - 1), Wa = n * Cv * (S.Th - T2a); return { g, pts: [[V1, V2, 'iso', S.Th], [V1, V2, 'adi', S.Th, V1]], W: Wi, Wa, T2a, Qin: Wi, eta: null, Pk }; }
  function pvPath(seg, Pk, g) { const [Va, Vb, type, Tq, Vref] = seg, out = []; for (let i = 0; i <= 80; i++) { const V = Va + (Vb - Va) * i / 80; let Pq; if (type === 'iso') Pq = Pk(Tq, V); else if (type === 'adi') Pq = Pk(Tq, Vref) * (Vref / V) ** g; else { const Tt = seg[3] + (seg[4] - seg[3]) * i / 80; Pq = Pk(Tt, Va); } out.push([V, Pq]); } return out; }
  Y.def({ id: 'pvcycle', kind: K.th, title: T('Thermodynamic processes and cycles on a PV diagram', 'العمليات الحرارية على مخطط PV'), unit: 'JEE Main · Thermodynamics', probe: 'show a Carnot cycle between 500 K and 300 K on a PV diagram and its efficiency',
    rx: /\b(pv[- ]diagrams?|p[- ]v diagrams?|carnot (cycle|engine|efficiency)|otto cycle|petrol engine cycle|heat engines?|thermodynamic (cycles?|processes?)|isothermal|adiabatic|isobaric|isochoric|work done by (an? |the )?(ideal )?gas|first law of thermodynamics|efficiency of (a |the )?(heat|carnot|otto|petrol) engine)\b/i, score: 0.95,
    sel: [['cycle', T('show', 'اعرض'), [['carnot', T('Carnot cycle', 'دورة كارنو'), /carnot/i], ['otto', T('Otto cycle (petrol engine)', 'دورة أوتو'), /otto|petrol/i], ['comp', T('isothermal vs adiabatic expansion', 'متساوي الحرارة مقابل الأديباتي'), /isothermal|adiabatic|process/i]], 'carnot'], ['gam', T('gas', 'الغاز'), [['mono', T('monatomic (γ = 5/3)', 'أحادي'), /monatomic|helium|argon/i], ['di', T('diatomic (γ = 7/5)', 'ثنائي'), /diatomic|air|nitrogen|oxygen/i]], 'mono']],
    p: [['Th', T('hot temperature T_H', 'T الساخنة'), 'K', 300, 2500, 10, 500, /(\d{3,4})\s*K\s*(?:and|to|hot|source)/i], ['Tc', T('cold temperature T_C', 'T الباردة'), 'K', 100, 1000, 10, 300, /(?:and|to|cold|sink)\s*(\d{2,4})\s*K/i], ['ratio', T('expansion / compression ratio', 'نسبة التمدد/الانضغاط'), '', 1.2, 12, 0.1, 2.5]],
    parse: t => (/\botto|petrol/i.test(t) ? { ratio: 8, Th: 1800, gam: 'di' } : {}),
    auto: true, view: S => { const r = cyc(S), all = r.pts.flatMap(s => pvPath(s, r.Pk, r.g)); return { x0: 0, x1: Math.max(...all.map(q => q[0])) * 1.1, y0: 0, y1: Math.max(...all.map(q => q[1])) * 1.1 }; }, labels: { x: 'V (L)', y: 'P (kPa)' },
    draw(p, S, c, H) { const r = cyc(S); if (S.cycle !== 'comp') { const loop = r.pts.flatMap(s => pvPath(s, r.Pk, r.g)); p.path(loop, c.pal[3], { w: 0.5, close: true, fill: 'rgba(217,119,6,.18)' }); }
      r.pts.forEach((s, i) => { const pts = pvPath(s, r.Pk, r.g); p.path(pts, S.cycle === 'comp' ? c.pal[i] : s[2] === 'iso' ? c.pal[3] : s[2] === 'adi' ? c.pal[0] : c.pal[1], { w: 2.6 }); if (S.cycle !== 'comp') { const m = pts[40]; H.lab(p, m[0], m[1], s[2] === 'iso' ? T('isothermal', 'متساوي الحرارة') : s[2] === 'adi' ? T('adiabatic', 'أديباتي') : T('constant V', 'حجم ثابت'), c.muted, { dy: -6 }); } });
      if (S.cycle === 'comp') { H.lab(p, r.pts[0][1] * 0.6, r.Pk(S.Th, r.pts[0][1] * 0.7), T('isothermal (PV = const)', 'متساوي الحرارة'), c.pal[0]); H.lab(p, r.pts[0][1] * 0.6, r.Pk(S.Th, 1) * (1 / (r.pts[0][1] * 0.7)) ** r.g, T('adiabatic (PV^γ = const), steeper', 'أديباتي أشد انحداراً'), c.pal[1], { dy: 14 }); } },
    ro: S => { const r = cyc(S); if (S.cycle === 'comp') return [[T('work, isothermal nRT ln(V₂/V₁)', 'الشغل متساوي الحرارة'), f3(r.W) + ' J'], [T('work, adiabatic nC_v(T₁ − T₂)', 'الشغل الأديباتي'), f3(r.Wa) + ' J'], [T('final T after adiabatic expansion', 'T النهائية'), f3(r.T2a) + ' K']]; return [[T('net work per cycle (shaded area)', 'الشغل الصافي'), f3(r.W) + ' J'], [T('heat taken in', 'الحرارة الداخلة'), f3(r.Qin) + ' J'], [T('efficiency W/Q_in', 'الكفاءة'), f3(r.eta * 100) + '%'], [S.cycle === 'carnot' ? '1 − T_C/T_H' : '1 − r^{1−γ}', f3(r.etaFormula * 100) + '%']]; },
    st: S => { const r = cyc(S); return { W: r.W, Qin: r.Qin, eta: r.eta, etaFormula: r.etaFormula, Wa: r.Wa, T2a: r.T2a }; },
    intro: S => { const r = cyc(S); return S.cycle === 'carnot' ? T(`One mole of ideal gas runs a Carnot cycle: isothermal expansion at ${S.Th} K, adiabatic expansion to ${S.Tc} K, isothermal compression, adiabatic compression. The shaded area is the net work, ${f3(r.W)} J per cycle. Its efficiency 1 − T_C/T_H = ${f3(r.etaFormula * 100)}% is the highest any engine between these temperatures can have.`, 'دورة كارنو.') : S.cycle === 'otto' ? T(`The Otto cycle (petrol engine): adiabatic compression by a ratio of ${S.ratio}, heating at constant volume (combustion), adiabatic expansion (power stroke), cooling at constant volume. Its efficiency depends only on the compression ratio: 1 − r^{1−γ} = ${f3(r.etaFormula * 100)}%.`, 'دورة أوتو.') : T(`Expanding from 1 L to ${S.ratio} L: at constant temperature the gas takes in heat and does ${f3(r.W)} J of work; adiabatically (no heat in) it cools to ${f3(r.T2a)} K and does less work, ${f3(r.Wa)} J, so its curve is steeper.`, 'مقارنة.'); },
    ex: () => P('First law: Q = ΔU + W, W = ∫P dV (area under the curve);  ΔU = nC_vΔT;  isothermal: W = nRT ln(V₂/V₁);  adiabatic: PV^γ = const, TV^{γ−1} = const, W = nC_v(T₁ − T₂);  Carnot: η = 1 − T_C/T_H;  Otto: η = 1 − r^{1−γ}.'), assume: T('1 mol of ideal gas, quasi-static (reversible) processes.', 'غاز مثالي.') });

  const GAS = { h2: ['H₂', 2.016], he: ['He', 4.0026], n2: ['N₂', 28.014], o2: ['O₂', 31.998], co2: ['CO₂', 44.01] };
  Y.def({ id: 'mbdist', kind: K.th, title: T('Maxwell–Boltzmann distribution of molecular speeds', 'توزيع ماكسويل-بولتزمان'), unit: 'JEE Main · Kinetic theory of gases', probe: 'show the Maxwell–Boltzmann speed distribution for nitrogen at 300 K and 600 K and the rms speed',
    rx: /\b(maxwell[- ]?boltzmann|speed distribution|distribution of (molecular )?speeds|most probable (speed|velocity)|rms (speed|velocity)|root[- ]mean[- ]square (speed|velocity)|average speed of (gas )?molecules|mean speed of (gas )?molecules)\b/i, score: 0.96,
    sel: [['gas', T('gas', 'الغاز'), [['n2', 'N₂', /nitrogen|\bN2\b|N₂/i], ['o2', 'O₂', /oxygen|\bO2\b/i], ['he', 'He', /helium/i], ['h2', 'H₂', /hydrogen|\bH2\b/i], ['co2', 'CO₂', /carbon dioxide|CO2/i]], 'n2']],
    p: [['T', T('temperature', 'درجة الحرارة'), 'K', 50, 2000, 10, 300, /(\d{2,4})\s*K\b/i], ['T2', T('compare with', 'قارن مع'), 'K', 0, 2000, 10, 600]],
    parse: t => { const m = [...String(t).matchAll(/(\d{2,4})\s*K\b/gi)]; return m.length >= 2 ? { T: +m[0][1], T2: +m[1][1] } : {}; },
    auto: true, view: S => { const vm = Math.sqrt(2 * R * Math.max(S.T, S.T2) / (GAS[S.gas][1] / 1e3)); const fm = mbf(Math.sqrt(2 * R * Math.min(S.T, S.T2 || S.T) / (GAS[S.gas][1] / 1e3)), Math.min(S.T, S.T2 || S.T), S); return { x0: 0, x1: vm * 3.2, y0: 0, y1: fm * 1.25 }; }, labels: { x: 'v (m/s)', y: 'f(v) (s/m)' },
    draw(p, S, c, H) { [S.T, S.T2].forEach((Tq, i) => { if (!Tq) return; const M = GAS[S.gas][1] / 1e3; H.curve(p, v => mbf(v, Tq, S), 0, p.view.x1, c.pal[i], { w: 2.6 }, 400); const vp = Math.sqrt(2 * R * Tq / M), va = Math.sqrt(8 * R * Tq / (Math.PI * M)), vr = Math.sqrt(3 * R * Tq / M); [[vp, 'v_p'], [va, 'v̄'], [vr, 'v_rms']].forEach(([v, l]) => { p.path([[v, 0], [v, mbf(v, Tq, S)]], c.pal[i], { w: 1, dash: [3, 3] }); H.lab(p, v, mbf(v, Tq, S), l, c.pal[i], { dy: -6, align: 'center' }); }); H.lab(p, p.view.x1 * 0.62, p.view.y1 * (0.9 - i * 0.08), `${GAS[S.gas][0]} at ${Tq} K`, c.pal[i]); }); },
    ro: S => { const M = GAS[S.gas][1] / 1e3; return [[T('most probable √(2RT/M)', 'الأكثر احتمالاً'), f3(Math.sqrt(2 * R * S.T / M)) + ' m/s'], [T('mean √(8RT/πM)', 'المتوسطة'), f3(Math.sqrt(8 * R * S.T / (Math.PI * M))) + ' m/s'], [T('rms √(3RT/M)', 'الجذر التربيعي'), f3(Math.sqrt(3 * R * S.T / M)) + ' m/s'], [T('average KE per molecule (3/2)kT', 'متوسط الطاقة'), f3(1.5 * kB * S.T) + ' J']]; },
    st: S => { const M = GAS[S.gas][1] / 1e3; return { vp: Math.sqrt(2 * R * S.T / M), vavg: Math.sqrt(8 * R * S.T / (Math.PI * M)), vrms: Math.sqrt(3 * R * S.T / M), area: (() => { let s = 0; const n = 4000, b = Math.sqrt(2 * R * S.T / M) * 8; for (let i = 0; i < n; i++) s += mbf((i + 0.5) * b / n, S.T, S); return s * b / n; })() }; },
    intro: S => T(`Molecules in a gas have a spread of speeds. The curve’s area is 1; its peak is the most probable speed. Heating from ${S.T} K${S.T2 ? ` to ${S.T2} K` : ''} shifts the curve to higher speeds and flattens it (the area stays 1). Always v_p < v̄ < v_rms, in the ratio 1 : 1.128 : 1.225.`, 'توزيع السرعات.'),
    ex: () => P('f(v) = 4π (M/2πRT)^{3/2} v² e^{−Mv²/2RT};  v_p : v̄ : v_rms = √2 : √(8/π) : √3;  KE_avg = (3/2)kT per molecule;  lighter gases are faster at the same temperature (v ∝ 1/√M).') });
  function mbf(v, Tq, S) { const M = GAS[S.gas][1] / 1e3, a = M / (2 * R * Tq); return 4 * Math.PI * (a / Math.PI) ** 1.5 * v * v * Math.exp(-a * v * v); }

  /* ---------- oscillations ---------- */
  Y.def({ id: 'shm', kind: K.osc, title: T('Simple harmonic motion as a rotating phasor', 'الحركة التوافقية البسيطة'), unit: 'JEE Main · Oscillations and waves', probe: 'explain simple harmonic motion with the reference circle and show how KE and PE change', anim: (S, st, h) => { st.ph = (st.ph || 0) + h * 2 * Math.PI * S.f * 0.5; },
    rx: /\b(simple harmonic motion|\bshm\b|s\.h\.m|phasor|reference circle|energy in (shm|simple harmonic)|x\s*=\s*a\s*sin\s*\(?\s*(ω|w)t|uniform circular motion and shm)\b/i, not: /\b(spring|pendulum|lc circuit)\b/i, score: 0.95,
    p: [['A', T('amplitude A', 'السعة'), 'm', 0.1, 2, 0.05, 1], ['f', T('frequency f', 'التردد'), 'Hz', 0.1, 3, 0.05, 0.5], ['phi', T('initial phase φ', 'الطور الابتدائي'), '°', 0, 360, 1, 0], ['m', T('mass', 'الكتلة'), 'kg', 0.1, 5, 0.1, 1]],
    view: { x0: -3, x1: 7.5, y0: -2.6, y1: 2.6 }, equal: true, labels: { x: '', y: 'x' },
    draw(p, S, c, H, st) { const th = (st.ph || 0) + rad(S.phi), A = S.A, x = A * Math.sin(th); H.circle(p, -1.4, 0, A, c.muted, { w: 1.2 }); const px = -1.4 + A * Math.cos(th); p.arrow(-1.4, 0, px, x, c.pal[0], 'A'); p.path([[px, x], [0.6, x]], c.muted, { w: 1, dash: [3, 3] }); p.dot(0.6, x, c.pal[1], '', { r: 7 });
      const w = 2 * Math.PI * S.f; H.curve(p, u => A * Math.sin(th - (u - 0.6) * w / 1.2), 0.6, 4.6, c.pal[1], { w: 2 }); const KE = 0.5 * S.m * (w * A * Math.cos(th)) ** 2, PE = 0.5 * S.m * (w * x) ** 2, E = 0.5 * S.m * (w * A) ** 2;
      [[KE, 'KE', c.pal[2]], [PE, 'PE', c.pal[3]]].forEach(([v, l, col], i) => { const bx = 5.8 + i * 0.8; p.path([[bx, -2], [bx, -2 + 4 * v / E]], col, { w: 14 }); H.lab(p, bx, -2.4, l, col, { align: 'center' }); }); },
    ro: (S, st) => { const w = 2 * Math.PI * S.f, th = (st && st.ph || 0) + rad(S.phi); return [['ω = 2πf', f3(w) + ' rad/s'], ['T = 1/f', f3(1 / S.f) + ' s'], [T('max speed Aω', 'أقصى سرعة'), f3(S.A * w) + ' m/s'], [T('max acceleration Aω²', 'أقصى تسارع'), f3(S.A * w * w) + ' m/s²'], [T('total energy ½mω²A²', 'الطاقة الكلية'), f3(0.5 * S.m * w * w * S.A * S.A) + ' J'], ['x', f3(S.A * Math.sin(th)) + ' m']]; },
    st: S => { const w = 2 * Math.PI * S.f; return { omega: w, period: 1 / S.f, vmax: S.A * w, amax: S.A * w * w, E: 0.5 * S.m * w * w * S.A * S.A }; },
    intro: S => T(`SHM is the shadow of uniform circular motion: a point going round a circle of radius A at ω = 2πf = ${f3(2 * Math.PI * S.f)} rad/s, seen side-on, moves as x = A sin(ωt + φ). Its speed is greatest at the centre and zero at the ends; its acceleration −ω²x always points to the centre. The bars show energy swapping between kinetic and potential while the total stays ½mω²A².`, 'ظل الحركة الدائرية.'),
    ex: () => P('x = A sin(ωt + φ);  v = Aω cos(ωt + φ) = ±ω√(A² − x²);  a = −ω²x;  KE = ½mω²(A² − x²), PE = ½mω²x²;  KE = PE at x = A/√2.') });

  function resAmp(S, w) { const w0 = 2 * Math.PI * S.f0, gm = S.b / S.m; return (S.F0 / S.m) / Math.sqrt((w0 * w0 - w * w) ** 2 + (gm * w) ** 2); }
  Y.def({ id: 'resonance', kind: K.osc, title: T('Forced oscillations, damping and resonance', 'الاهتزازات القسرية والرنين'), unit: 'JEE Main · Oscillations (damped and forced)', probe: 'show the resonance curve of a driven oscillator and how damping changes it',
    rx: /\b(resonance|resonant (frequency|curve)|forced (oscillations?|vibrations?)|driven (oscillators?|oscillations?|harmonic)|damped (oscillations?|harmonic|motion)|damping|quality factor|q[- ]factor|amplitude resonance)\b/i, not: /\b(lcr|rlc|lc circuit|series circuit|ac circuit|electrical|tuning a radio)\b/i, score: 0.94,
    p: [['m', T('mass', 'الكتلة'), 'kg', 0.1, 10, 0.1, 1], ['f0', T('natural frequency f₀', 'التردد الطبيعي'), 'Hz', 0.2, 5, 0.05, 1], ['b', T('damping b', 'التخميد'), 'kg/s', 0.01, 10, 0.01, 0.6], ['F0', T('driving force amplitude', 'سعة القوة'), 'N', 0.1, 10, 0.1, 1], ['fd', T('driving frequency', 'تردد القوة'), 'Hz', 0.05, 5, 0.01, 0.9]],
    auto: true, view: S => { const pk = resAmp(S, 2 * Math.PI * S.f0 * Math.sqrt(Math.max(0.01, 1 - (S.b / S.m) ** 2 / (8 * Math.PI * Math.PI * S.f0 * S.f0)))); return { x0: 0, x1: S.f0 * 3, y0: 0, y1: pk * 1.2 }; }, labels: { x: T('driving frequency (Hz)', 'تردد القوة'), y: T('amplitude (m)', 'السعة') },
    draw(p, S, c, H) { H.curve(p, f => resAmp(S, 2 * Math.PI * f), 0.001, p.view.x1, c.pal[0], { w: 2.6 }, 600); H.curve(p, f => resAmp(Object.assign({}, S, { b: S.b * 3 }), 2 * Math.PI * f), 0.001, p.view.x1, c.muted, { w: 1.4, dash: [6, 4] }, 600); p.dot(S.fd, resAmp(S, 2 * Math.PI * S.fd), c.pal[3], T('driving here', 'هنا')); p.path([[S.f0, 0], [S.f0, p.view.y1]], c.muted, { w: 1, dash: [3, 4] }); H.lab(p, S.f0, p.view.y1 * 0.95, 'f₀', c.muted, { dx: 4 }); H.lab(p, S.f0 * 1.6, p.view.y1 * 0.85, T('dashed: 3× the damping', 'المتقطع: تخميد ×3'), c.muted); },
    ro: S => { const w0 = 2 * Math.PI * S.f0, gm = S.b / S.m, wr = w0 * w0 - gm * gm / 2 > 0 ? Math.sqrt(w0 * w0 - gm * gm / 2) : 0, w = 2 * Math.PI * S.fd; return [[T('amplitude at this driving frequency', 'السعة هنا'), f3(resAmp(S, w)) + ' m'], [T('resonance (peak) frequency', 'تردد الرنين'), f3(wr / (2 * Math.PI)) + ' Hz'], [T('peak amplitude', 'أقصى سعة'), wr ? f3(resAmp(S, wr)) + ' m' : '—'], ['Q = ω₀m/b', f3(w0 * S.m / S.b)], [T('phase lag of x behind F', 'تأخر الطور'), f3(deg(Math.atan2(gm * w, w0 * w0 - w * w))) + '°']]; },
    st: S => { const w0 = 2 * Math.PI * S.f0, gm = S.b / S.m, wr = Math.sqrt(Math.max(0, w0 * w0 - gm * gm / 2)); return { amp: resAmp(S, 2 * Math.PI * S.fd), fres: wr / (2 * Math.PI), Q: w0 * S.m / S.b, phaseDeg: deg(Math.atan2(gm * 2 * Math.PI * S.fd, w0 * w0 - (2 * Math.PI * S.fd) ** 2)) }; },
    intro: S => T(`Driving an oscillator near its natural frequency f₀ = ${S.f0} Hz builds up a large amplitude: resonance. Damping limits the peak and widens it — compare the dashed curve with three times the damping. The sharpness is measured by Q = ${f3(2 * Math.PI * S.f0 * S.m / S.b)}.`, 'الرنين.'),
    ex: () => P('m ẍ + b ẋ + kx = F₀ cos ωt;  steady state A(ω) = (F₀/m)/√[(ω₀² − ω²)² + (bω/m)²];  peak at ω_r = √(ω₀² − b²/2m²);  phase lag 90° at ω = ω₀.') });

  /* ---------- electrostatics: capacitors ---------- */
  function capnet(S) { const { C1, C2, C3, V } = S, ser = (...a) => 1 / a.reduce((s, x) => s + 1 / x, 0); let Ceq, q = {}, v = {};
    if (S.top === 'series') { Ceq = ser(C1, C2, C3); const Q = Ceq * V; [['1', C1], ['2', C2], ['3', C3]].forEach(([k, C]) => { q[k] = Q; v[k] = Q / C; }); }
    else if (S.top === 'parallel') { Ceq = C1 + C2 + C3; [['1', C1], ['2', C2], ['3', C3]].forEach(([k, C]) => { v[k] = V; q[k] = C * V; }); }
    else if (S.top === 'p12s3') { const Cp = C1 + C2; Ceq = ser(Cp, C3); const Q = Ceq * V, Vp = Q / Cp; v['1'] = v['2'] = Vp; q['1'] = C1 * Vp; q['2'] = C2 * Vp; q['3'] = Q; v['3'] = Q / C3; }
    else { const Cs = ser(C1, C2); Ceq = Cs + C3; const Qs = Cs * V; q['1'] = q['2'] = Qs; v['1'] = Qs / C1; v['2'] = Qs / C2; v['3'] = V; q['3'] = C3 * V; }
    const U = Object.fromEntries(['1', '2', '3'].map(k => [k, 0.5 * q[k] * v[k]])); return { Ceq, q, v, U, Utot: 0.5 * Ceq * V * V }; }
  Y.def({ id: 'capnet', kind: K.es, title: T('Capacitor networks: series and parallel', 'شبكات المكثفات'), unit: 'JEE Main · Electrostatics (capacitance)', probe: 'capacitors of 2 µF and 3 µF in parallel are in series with 5 µF across 10 V: find the charge and voltage on each',
    rx: /\b(capacitors?\b.*\b(series|parallel)|(series|parallel)\b.*\bcapacitors?|capacitor (networks?|combinations?|circuits?)|equivalent capacitance|combination of capacitors|charge on (each|the) capacitors?|energy stored in (the |each |a )?capacitors?)\b/i, not: /\b(dielectric|charging|discharging|time constant|rc\b|slab|parallel[- ]plate)\b/i, score: 0.96,
    sel: [['top', T('connection', 'التوصيل'), [['series', T('all in series', 'على التوالي'), /all\s*(?:three\s*)?in series|in series$/i], ['parallel', T('all in parallel', 'على التوازي'), /all\s*(?:three\s*)?in parallel/i], ['p12s3', T('(C₁ ∥ C₂) in series with C₃', '(C₁∥C₂) مع C₃'), /parallel\b.*\bin series with/i], ['s12p3', T('(C₁ – C₂ in series) ∥ C₃', '(C₁-C₂) ∥ C₃'), /series\b.*\bin parallel with/i]], 'p12s3']],
    p: [['C1', 'C₁', 'µF', 0.5, 20, 0.5, 2], ['C2', 'C₂', 'µF', 0.5, 20, 0.5, 3], ['C3', 'C₃', 'µF', 0.5, 20, 0.5, 5], ['V', T('battery', 'البطارية'), 'V', 1, 100, 1, 10, /(\d+(?:\.\d+)?)\s*V\b/i]],
    parse: t => { const a = [...String(t).matchAll(/(\d+(?:\.\d+)?)\s*(?:µ|μ|u)F/gi)]; const o = {}; a.slice(0, 3).forEach((m, i) => { o['C' + (i + 1)] = +m[1]; }); return o; },
    view: { x0: 0, x1: 12, y0: 0, y1: 7 }, grid: false, labels: { x: '', y: '' },
    draw(p, S, c, H) { const r = capnet(S), cap = (x, y, lab, vert) => { const g = 0.18; if (vert) { p.path([[x - 0.5, y + g], [x + 0.5, y + g]], c.ink, { w: 3 }); p.path([[x - 0.5, y - g], [x + 0.5, y - g]], c.ink, { w: 3 }); H.lab(p, x + 0.6, y, lab, c.pal[0]); } else { p.path([[x - g, y - 0.5], [x - g, y + 0.5]], c.ink, { w: 3 }); p.path([[x + g, y - 0.5], [x + g, y + 0.5]], c.ink, { w: 3 }); H.lab(p, x, y + 0.75, lab, c.pal[0], { align: 'center' }); } };
      const w = (pts) => p.path(pts, c.ink, { w: 1.8 }), lb = k => `C${'₁₂₃'[k - 1]} ${S['C' + k]}µF · ${f3(r.q[k])}µC · ${f3(r.v[k])}V`;
      w([[1, 1], [1, 6], [11, 6], [11, 1], [6.3, 1]]); w([[5.7, 1], [1, 1]]); p.path([[5.7, 0.6], [5.7, 1.4]], c.ink, { w: 3 }); p.path([[6.3, 0.75], [6.3, 1.25]], c.ink, { w: 3 }); H.lab(p, 6, 0.2, `${S.V} V`, c.ink, { align: 'center' });
      if (S.top === 'series') { [3, 6, 9].forEach((x, i) => { p.path([[x - 0.3, 6], [x + 0.3, 6]], c.bg || '#fff', { w: 6 }); cap(x, 6, lb(i + 1)); }); }
      else if (S.top === 'parallel') { [3, 6, 9].forEach((x, i) => { w([[x, 6], [x, 1]]); p.path([[x, 3.2], [x, 3.8]], c.bg || '#fff', { w: 6 }); cap(x, 3.5, lb(i + 1), true); }); }
      else if (S.top === 'p12s3') { w([[3, 6], [3, 3.5], [6, 3.5], [6, 6]]); p.path([[3, 6], [6, 6]], c.bg || '#fff', { w: 6 }); w([[3, 6], [3, 6.8], [6, 6.8], [6, 6]]); cap(4.5, 6.8, lb(1)); cap(4.5, 3.5, lb(2)); p.path([[8.7, 6], [9.3, 6]], c.bg || '#fff', { w: 6 }); cap(9, 6, lb(3)); }
      else { p.path([[2.7, 6], [3.3, 6]], c.bg || '#fff', { w: 6 }); cap(3, 6, lb(1)); p.path([[6.7, 6], [7.3, 6]], c.bg || '#fff', { w: 6 }); cap(7, 6, lb(2)); w([[1.5, 6], [1.5, 3], [10.5, 3], [10.5, 6]]); p.path([[5.7, 3], [6.3, 3]], c.bg || '#fff', { w: 6 }); cap(6, 3, lb(3)); } },
    ro: S => { const r = capnet(S); return [[T('equivalent capacitance', 'السعة المكافئة'), f3(r.Ceq) + ' µF'], [T('charge from the battery', 'الشحنة الكلية'), f3(r.Ceq * S.V) + ' µC'], ...['1', '2', '3'].map(k => [`C${'₁₂₃'[k - 1]}: Q, V, U`, `${f3(r.q[k])} µC, ${f3(r.v[k])} V, ${f3(r.U[k])} µJ`]), [T('total energy ½C_eqV²', 'الطاقة الكلية'), f3(r.Utot) + ' µJ']]; },
    st: S => capnet(S),
    intro: S => { const r = capnet(S); return T(`In series, capacitors carry the same charge and share the voltage (1/C = Σ1/Cᵢ); in parallel they share the same voltage and add their charges (C = ΣCᵢ). This network is equivalent to ${f3(r.Ceq)} µF, so the battery supplies ${f3(r.Ceq * S.V)} µC. Each capacitor’s charge, voltage and energy are labelled.`, 'توالي وتوازي.'); },
    ex: () => P('Series: 1/C = Σ1/Cᵢ, same Q;  parallel: C = ΣCᵢ, same V;  U = ½CV² = Q²/2C = ½QV.') });

  Y.def({ id: 'dielectric', kind: K.es, title: T('Parallel-plate capacitor with a dielectric', 'مكثف ذو لوحين متوازيين مع عازل'), unit: 'JEE Main · Electrostatics (capacitance)', probe: 'a parallel-plate capacitor with plates 100 cm² and 2 mm apart gets a 1 mm slab of K = 4: what is the new capacitance?',
    rx: /\b(dielectric (slab|constant|material|inserted|between)?|parallel[- ]plate capacitors?|capacitance of (a |the )?parallel[- ]plate|permittivity|slab (of|with) (dielectric|k\s*=)|slab of k)\b/i, score: 0.96,
    p: [['A', T('plate area', 'مساحة اللوح'), 'cm²', 1, 1000, 1, 100, /(\d+(?:\.\d+)?)\s*cm(?:²|\^?2)/i], ['d', T('plate separation', 'المسافة'), 'mm', 0.1, 20, 0.1, 2, /(\d+(?:\.\d+)?)\s*mm\s*(?:apart|separation|gap)/i], ['t', T('slab thickness', 'سمك العازل'), 'mm', 0, 20, 0.1, 1, /(\d+(?:\.\d+)?)\s*mm\s*(?:thick\s*)?(?:slab|dielectric)/i], ['K', T('dielectric constant K', 'ثابت العزل'), '', 1, 100, 0.1, 4, /K\s*=\s*(\d+(?:\.\d+)?)/i], ['V', T('battery', 'البطارية'), 'V', 1, 1000, 1, 100]],
    tog: [['conn', T('battery stays connected', 'البطارية موصولة'), true, /\bconnected\b/i]],
    view: { x0: -1, x1: 11, y0: -1, y1: 7 }, grid: false, labels: { x: '', y: '' },
    draw(p, S, c, H) { const t = Math.min(S.t, S.d), sc = 5 / S.d; p.path([[1, 6], [9, 6]], c.pal[1], { w: 5 }); p.path([[1, 6 - S.d * sc], [9, 6 - S.d * sc]], c.pal[0], { w: 5 }); H.lab(p, 9.3, 6, '+Q', c.pal[1]); H.lab(p, 9.3, 6 - S.d * sc, '−Q', c.pal[0]);
      if (t > 0) p.path([[2, 6 - S.d * sc], [8, 6 - S.d * sc], [8, 6 - S.d * sc + t * sc], [2, 6 - S.d * sc + t * sc]], c.pal[3], { w: 1, close: true, fill: 'rgba(217,119,6,.3)' }); if (t > 0) H.lab(p, 5, 6 - S.d * sc + t * sc / 2, `K = ${S.K}`, c.pal[3], { align: 'center' });
      const r = diel(S); for (let x = 2.5; x < 8; x += 1.1) { const y0 = 6, y1 = 6 - S.d * sc; p.arrow(x, y0 - 0.1, x, y1 + 0.2, c.muted, '', { w: 1 }); } H.lab(p, 0, 6.6, T(`E in air ${f3(r.Eair)} V/m · in the slab ${f3(r.Eslab)} V/m`, 'المجال'), c.ink); },
    ro: S => { const r = diel(S); return [['C₀ = ε₀A/d', f3(r.C0 * 1e12) + ' pF'], ['C = ε₀A/(d − t + t/K)', f3(r.C * 1e12) + ' pF'], [T('charge Q', 'الشحنة'), f3(r.Q * 1e9) + ' nC'], [T('voltage across', 'الجهد'), f3(r.Vc) + ' V'], [T('stored energy', 'الطاقة'), f3(r.U * 1e6) + ' µJ']]; },
    st: S => diel(S),
    intro: S => { const r = diel(S); return T(`The slab’s molecules polarise and partly cancel the field inside it (E falls by K there), so for the same charge the voltage is lower and the capacitance rises from ${f3(r.C0 * 1e12)} pF to ${f3(r.C * 1e12)} pF. ${S.conn ? 'With the battery connected V stays fixed, so the charge (and energy) increase.' : 'With the battery removed Q stays fixed, so the voltage and stored energy drop.'}`, 'العازل يزيد السعة.'); },
    ex: () => P('Full slab: C = Kε₀A/d.  Slab of thickness t: C = ε₀A/(d − t + t/K) (a metal slab: K → ∞, C = ε₀A/(d − t)).  Battery connected: V fixed, Q and U ×(C/C₀); isolated: Q fixed, V and U ÷(C/C₀).') });
  function diel(S) { const A = S.A * 1e-4, d = S.d * 1e-3, t = Math.min(S.t, S.d) * 1e-3, C0 = eps0 * A / d, C = eps0 * A / (d - t + t / S.K); const Q = S.conn ? C * S.V : C0 * S.V, Vc = Q / C, sig = Q / A; return { C0, C, Q, Vc, U: 0.5 * Q * Vc, Eair: sig / eps0, Eslab: sig / (eps0 * S.K) }; }

  /* ---------- transients and AC ---------- */
  const TR = { rcc: { names: ['q/Q₀', 'i/i₀'], y0: () => [0], f: (t, y, S) => [(S.V - y[0] / (S.C * 1e-6)) / S.R], tau: S => S.R * S.C * 1e-6 }, rcd: { y0: S => [S.C * 1e-6 * S.V], f: (t, y, S) => [-y[0] / (S.R * S.C * 1e-6)], tau: S => S.R * S.C * 1e-6 }, rl: { y0: () => [0], f: (t, y, S) => [(S.V - y[0] * S.R) / (S.L * 1e-3)], tau: S => S.L * 1e-3 / S.R }, lc: { y0: S => [S.C * 1e-6 * S.V, 0], f: (t, y, S) => [y[1], -y[0] / (S.L * 1e-3 * S.C * 1e-6)], tau: S => 2 * Math.PI * Math.sqrt(S.L * 1e-3 * S.C * 1e-6) }, rlc: { y0: S => [S.C * 1e-6 * S.V, 0], f: (t, y, S) => [y[1], (-S.R * y[1] - y[0] / (S.C * 1e-6)) / (S.L * 1e-3)], tau: S => 2 * Math.PI * Math.sqrt(S.L * 1e-3 * S.C * 1e-6) } };
  Y.def({ id: 'transient', kind: K.ac, title: T('RC, RL and LC circuits over time', 'دوائر RC وRL وLC'), unit: 'JEE Main · Current electricity / EMI', probe: 'show how a 100 µF capacitor charges through a 10 kΩ resistor from 12 V and what the time constant means',
    rx: /\b(rc circuits?|charging (of )?(a |the )?capacitors?|discharging (of )?(a |the )?capacitors?|capacitor (charges|discharges|charging|discharging)|time constant|rl circuits?|lc (circuits?|oscillations?|oscillator)|rlc (circuit )?(transient|discharge|oscillation)|growth of current (in )?(an |the )?inductor|decay of current (in )?(an |the )?inductor)\b/i, not: /\b(ac source|alternating|impedance|reactance|phasor)\b/i, score: 0.95,
    sel: [['type', T('circuit', 'الدائرة'), [['rcc', T('RC charging', 'شحن RC'), /charg(?!e on)/i], ['rcd', T('RC discharging', 'تفريغ RC'), /discharg/i], ['rl', T('RL: current growth', 'نمو التيار RL'), /\brl\b|inductor/i], ['lc', T('LC oscillation', 'اهتزاز LC'), /\blc\b/i], ['rlc', T('RLC damped oscillation', 'RLC مخمد'), /\brlc\b|damped/i]], 'rcc']],
    p: [['R', 'R', 'Ω', 1, 100000, 1, 10000, /(\d+(?:\.\d+)?)\s*k\s*Ω|(\d+(?:\.\d+)?)\s*kohm/i], ['C', 'C', 'µF', 0.01, 1000, 0.01, 100, /(\d+(?:\.\d+)?)\s*(?:µ|μ|u)F/i], ['L', 'L', 'mH', 0.1, 10000, 0.1, 100, /(\d+(?:\.\d+)?)\s*mH/i], ['V', T('battery', 'البطارية'), 'V', 1, 100, 0.5, 12, /(\d+(?:\.\d+)?)\s*V\b/i]],
    parse: t => { const o = {}; const k = String(t).match(/(\d+(?:\.\d+)?)\s*k\s*(?:Ω|ohm)/i); if (k) o.R = +k[1] * 1000; else { const r = String(t).match(/(\d+(?:\.\d+)?)\s*(?:Ω|ohms?)\b/i); if (r) o.R = +r[1]; } return o; },
    ode: { y0: S => TR[S.type].y0(S), f: (t, y, S) => TR[S.type].f(t, y, S), T: S => (['lc', 'rlc'].includes(S.type) ? 3 : 5) * TR[S.type].tau(S), names: ['y'], plot: [['q or i', 0]], tlabel: 't (s)' },
    view: { x0: 0, x1: 1, y0: 0, y1: 1 }, grid: false, labels: { x: '', y: '' },
    draw(p, S, c, H, st) { const tau = TR[S.type].tau(S), tt = st.tt || 0, y = (st.y || [0])[0]; H.lab(p, 0.05, 0.85, S.type === 'rl' ? T(`current i = ${f3(y * 1e3)} mA`, 'التيار') : T(`charge q = ${f3(y * 1e6)} µC`, 'الشحنة'), c.pal[0], { font: '600 16px ui-sans-serif' }); H.lab(p, 0.05, 0.7, `t = ${f3(tt)} s = ${f3(tt / tau)} ${['lc', 'rlc'].includes(S.type) ? 'T' : 'τ'}`, c.muted); H.lab(p, 0.05, 0.5, ['lc', 'rlc'].includes(S.type) ? T('energy sloshes between C (electric) and L (magnetic)', 'تتبادل الطاقة') : T('after one τ: 63% of the way; after 5τ: > 99%', 'بعد τ: 63%'), c.ink); },
    ro: S => { const tau = TR[S.type].tau(S), rc = S.R * S.C * 1e-6, w0 = 1 / Math.sqrt(S.L * 1e-3 * S.C * 1e-6); return S.type === 'rcc' || S.type === 'rcd' ? [['τ = RC', f3(rc) + ' s'], [T('final charge CV', 'الشحنة النهائية'), f3(S.C * S.V) + ' µC'], [T('initial current V/R', 'التيار الابتدائي'), f3(S.V / S.R * 1e3) + ' mA'], [T('charge after one τ', 'بعد τ'), f3(S.C * S.V * (S.type === 'rcc' ? 1 - Math.exp(-1) : Math.exp(-1))) + ' µC']] : S.type === 'rl' ? [['τ = L/R', f3(tau) + ' s'], [T('final current V/R', 'التيار النهائي'), f3(S.V / S.R * 1e3) + ' mA']] : [['ω₀ = 1/√(LC)', f3(w0) + ' rad/s'], ['f₀', f3(w0 / (2 * Math.PI)) + ' Hz'], ...(S.type === 'rlc' ? [[T('damping', 'التخميد'), S.R < 2 * Math.sqrt(S.L * 1e-3 / (S.C * 1e-6)) ? T('underdamped (oscillates)', 'تحت التخميد') : T('overdamped (no oscillation)', 'فوق التخميد')]] : [])]; },
    st: S => ({ tau: TR[S.type].tau(S), qAtTau: S.C * 1e-6 * S.V * (S.type === 'rcc' ? 1 - Math.exp(-1) : Math.exp(-1)), iFinal: S.V / S.R, f0: 1 / (2 * Math.PI * Math.sqrt(S.L * 1e-3 * S.C * 1e-6)) }),
    intro: S => (S.type === 'rcc' ? T(`Through R the capacitor charges quickly at first and then ever more slowly: q = CV(1 − e^{−t/RC}). The time constant RC = ${f3(S.R * S.C * 1e-6)} s is how long it takes to reach 63%.`, 'شحن المكثف.') : S.type === 'rcd' ? T(`Discharging, the charge falls as q = Q₀e^{−t/RC}: down to 37% after each RC = ${f3(S.R * S.C * 1e-6)} s.`, 'تفريغ المكثف.') : S.type === 'rl' ? T(`An inductor opposes changes in current, so the current grows gradually: i = (V/R)(1 − e^{−Rt/L}), τ = L/R = ${f3(S.L * 1e-3 / S.R)} s.`, 'نمو التيار.') : T(`A charged capacitor across an inductor oscillates: charge flows back and forth at f₀ = 1/(2π√(LC)) = ${f3(1 / (2 * Math.PI * Math.sqrt(S.L * 1e-3 * S.C * 1e-6)))} Hz${S.type === 'rlc' ? ', the resistance draining energy each cycle' : ''}.`, 'اهتزاز LC.')),
    ex: () => P('RC: q = CV(1 − e^{−t/RC}), i = (V/R)e^{−t/RC};  RL: i = (V/R)(1 − e^{−t/τ}), τ = L/R;  LC: q = Q₀ cos ω₀t, ω₀ = 1/√(LC);  RLC: underdamped if R < 2√(L/C).') });

  function lcr(S) { const w = 2 * Math.PI * S.f, XL = w * S.L * 1e-3, XC = 1 / (w * S.C * 1e-6), Z = Math.hypot(S.R, XL - XC), I = S.V / Z, phi = Math.atan2(XL - XC, S.R); const f0 = 1 / (2 * Math.PI * Math.sqrt(S.L * 1e-3 * S.C * 1e-6)); return { XL, XC, Z, I, phiDeg: deg(phi), pf: Math.cos(phi), P: I * I * S.R, f0, VR: I * S.R, VL: I * XL, VC: I * XC, Q: Math.sqrt(S.L * 1e-3 / (S.C * 1e-6)) / S.R }; }
  Y.def({ id: 'lcr', kind: K.ac, title: T('Series LCR circuit: impedance, phasors and resonance', 'دائرة LCR المتتالية'), unit: 'JEE Main · Electromagnetic induction and alternating currents', probe: 'a series LCR circuit has R = 30 Ω, L = 100 mH and C = 50 µF on 220 V, 50 Hz: find the impedance, current and power factor',
    rx: /\b(lcr|series rlc|rlc (series|circuit)|ac circuits?|alternating current|impedance|reactance|phasor diagrams?|power factor|resonant frequency of (an? )?(lc|lcr|rlc)|rms (current|voltage)|wattless current|choke coil)\b/i, not: /\btransient|discharg|time constant\b/i, score: 0.95,
    p: [['R', 'R', 'Ω', 1, 500, 1, 30, /R\s*=\s*(\d+(?:\.\d+)?)/i], ['L', 'L', 'mH', 1, 2000, 1, 100, /(\d+(?:\.\d+)?)\s*mH/i], ['C', 'C', 'µF', 1, 500, 1, 50, /(\d+(?:\.\d+)?)\s*(?:µ|μ|u)F/i], ['V', T('rms voltage', 'الجهد الفعال'), 'V', 1, 400, 1, 220, /(\d+(?:\.\d+)?)\s*V\b/i], ['f', T('frequency', 'التردد'), 'Hz', 1, 500, 0.5, 50, /(\d+(?:\.\d+)?)\s*Hz/i]],
    view: { x0: -4, x1: 10, y0: -5, y1: 5 }, equal: true, grid: false, labels: { x: '', y: '' },
    draw(p, S, c, H) { const r = lcr(S), k = 4 / Math.max(r.VR, r.VL, r.VC, S.V); p.arrow(-3, 0, -3 + r.VR * k, 0, c.pal[0], 'V_R'); p.arrow(-3, 0, -3, r.VL * k, c.pal[1], 'V_L'); p.arrow(-3, 0, -3, -r.VC * k, c.pal[2], 'V_C'); p.arrow(-3, 0, -3 + r.VR * k, (r.VL - r.VC) * k, c.ink, `V (φ = ${f3(r.phiDeg)}°)`, { w: 3 });
      const fx = f => 1.5 + 8 * f / (r.f0 * 3), Imax = S.V / S.R; H.param(p, f => fx(f), f => -4 + 7 * (S.V / Math.hypot(S.R, 2 * Math.PI * f * S.L * 1e-3 - 1 / (2 * Math.PI * f * S.C * 1e-6))) / Imax, r.f0 * 0.02, r.f0 * 3, c.pal[3], { w: 2 }, 500);
      p.path([[1.5, -4], [9.5, -4]], c.muted, { w: 1 }); p.dot(fx(S.f), -4 + 7 * r.I / Imax, c.pal[3], T('here', 'هنا')); H.lab(p, fx(r.f0), 3.4, `f₀ = ${f3(r.f0)} Hz`, c.pal[3], { align: 'center' }); H.lab(p, 1.5, 4.4, T('current vs frequency', 'التيار مقابل التردد'), c.muted); },
    ro: S => { const r = lcr(S); return [['X_L = ωL', f3(r.XL) + ' Ω'], ['X_C = 1/(ωC)', f3(r.XC) + ' Ω'], ['Z = √(R² + (X_L − X_C)²)', f3(r.Z) + ' Ω'], ['I_rms = V/Z', f3(r.I) + ' A'], [T('phase φ (V ahead of I)', 'الطور'), f3(r.phiDeg) + '°'], [T('power factor cos φ', 'معامل القدرة'), f3(r.pf)], [T('average power I²R', 'القدرة'), f3(r.P) + ' W'], ['f₀ = 1/(2π√(LC))', f3(r.f0) + ' Hz']]; },
    st: S => lcr(S),
    intro: S => { const r = lcr(S); return T(`The resistor’s voltage is in phase with the current, the inductor’s leads it by 90° and the capacitor’s lags by 90°, so they add as arrows (phasors), not as numbers. Here X_L = ${f3(r.XL)} Ω and X_C = ${f3(r.XC)} Ω, giving Z = ${f3(r.Z)} Ω and I = ${f3(r.I)} A; the circuit is ${r.XL > r.XC ? 'inductive (V leads I)' : r.XL < r.XC ? 'capacitive (V lags I)' : 'at resonance'}. At f₀ = ${f3(r.f0)} Hz the reactances cancel and the current peaks.`, 'المتجهات الطورية.'); },
    ex: () => P('Z = √(R² + (X_L − X_C)²), tan φ = (X_L − X_C)/R, P = V_rms I_rms cos φ = I²R;  resonance ω₀ = 1/√(LC), Z = R;  Q = (1/R)√(L/C);  V_rms = V₀/√2.') });

  /* ---------- EM waves, polarisation ---------- */
  const BANDS = [[1e-11, T('gamma rays', 'أشعة غاما')], [1e-8, T('X-rays', 'أشعة سينية')], [4e-7, T('ultraviolet', 'فوق بنفسجية')], [7e-7, T('visible light', 'ضوء مرئي')], [1e-3, T('infrared', 'تحت حمراء')], [1, T('microwaves', 'موجات دقيقة')], [Infinity, T('radio waves', 'موجات راديو')]];
  Y.def({ id: 'emwave', kind: K.emw, title: T('Electromagnetic waves and the spectrum', 'الموجات الكهرومغناطيسية'), unit: 'JEE Main · Electromagnetic waves', probe: 'show an electromagnetic wave with its E and B fields and where 500 nm sits in the spectrum',
    rx: /\b(electromagnetic (waves?|spectrum|radiation)|em (waves?|spectrum|radiation)|displacement current|e and b fields? (in|of) (a |an )?(light|em|electromagnetic))\b/i, not: /\b(photoelectric|induction|induced emf)\b/i, score: 0.94,
    p: [['lnl', T('wavelength (log₁₀ of metres)', 'الطول الموجي (لوغاريتم)'), '', -12, 3, 0.05, -6.3], ['E0', T('electric field amplitude E₀', 'سعة المجال الكهربائي'), 'V/m', 1, 1000, 1, 100]],
    parse: t => { const m = String(t).match(/(\d+(?:\.\d+)?)\s*(nm|µm|um|mm|cm|m)\b/i); if (!m) return {}; const k = { nm: 1e-9, µm: 1e-6, um: 1e-6, mm: 1e-3, cm: 1e-2, m: 1 }[m[2].toLowerCase()]; return { lnl: +Math.log10(+m[1] * k).toFixed(2) }; },
    view: { x0: 0, x1: 10, y0: -3.2, y1: 3.2 }, grid: false, labels: { x: '', y: '' },
    draw(p, S, c, H) { p.path([[0, 0], [10, 0]], c.ink, { w: 1.4 }); H.curve(p, x => 2 * Math.sin(x * 2), 0, 10, c.pal[1], { w: 2.4 }); H.curve(p, x => -1 * Math.sin(x * 2), 0, 10, c.pal[0], { w: 2.4, dash: [6, 3] }); for (let x = 0.2; x < 10; x += 0.4) { p.path([[x, 0], [x, 2 * Math.sin(x * 2)]], c.pal[1], { w: 0.8 }); }
      H.lab(p, 0.1, 2.8, T('E (in the page)', 'E'), c.pal[1]); H.lab(p, 0.1, -2.6, T('B (dashed: perpendicular to the page, drawn foreshortened)', 'B عمودي'), c.pal[0]); p.arrow(8.6, 2.6, 9.9, 2.6, c.ink, 'c'); },
    ro: S => { const lam = 10 ** S.lnl, f = c0 / lam, band = BANDS.find(b => lam < b[0])[1]; return [['λ', f3(lam) + ' m'], ['f = c/λ', f3(f) + ' Hz'], [T('photon energy hf', 'طاقة الفوتون'), f3(h * f / e) + ' eV'], [T('band', 'النطاق'), band], ['B₀ = E₀/c', f3(S.E0 / c0) + ' T'], [T('intensity ½ε₀cE₀²', 'الشدة'), f3(0.5 * eps0 * c0 * S.E0 * S.E0) + ' W/m²']]; },
    st: S => { const lam = 10 ** S.lnl; return { f: c0 / lam, eV: h * c0 / lam / e, B0: S.E0 / c0, I: 0.5 * eps0 * c0 * S.E0 * S.E0 }; },
    intro: S => { const lam = 10 ** S.lnl; return T(`An EM wave is oscillating electric and magnetic fields, perpendicular to each other and to the direction of travel, moving at c. Its wavelength decides what we call it — ${f3(lam)} m is ${BANDS.find(b => lam < b[0])[1]} — and every photon carries hf = ${f3(h * c0 / lam / e)} eV.`, 'موجة كهرومغناطيسية.'); },
    ex: () => P('c = 1/√(μ₀ε₀) = fλ;  E₀ = cB₀;  E ⊥ B ⊥ direction;  intensity I = ½ε₀cE₀²;  radiation pressure I/c (absorbed).') });

  Y.def({ id: 'malus', kind: K.emw, title: T('Polarisation: Malus’s law and Brewster’s angle', 'الاستقطاب'), unit: 'JEE Main · Optics (wave optics)', probe: 'unpolarised light passes through two polarisers at 60°: what fraction gets through?',
    rx: /\b(malus'?s? law|polari[sz](er|ers|ation|ing|ed light)|polaroids?|analy[sz]er|brewster'?s? (angle|law)|crossed polari)\b/i, score: 0.96,
    p: [['th', T('angle between polariser and analyser', 'الزاوية'), '°', 0, 180, 1, 60, /(\d+(?:\.\d+)?)\s*(?:°|degrees?)/i], ['I0', T('incident intensity', 'الشدة الساقطة'), 'W/m²', 1, 1000, 1, 100], ['n', T('refractive index (for Brewster)', 'معامل الانكسار'), '', 1, 2.5, 0.01, 1.5]],
    tog: [['three', T('a third polariser at 45° in between', 'مستقطب ثالث'), false, /three polari|third polari|middle polari/i]],
    view: { x0: 0, x1: 180, y0: 0, y1: 0.55 }, labels: { x: T('angle θ (°)', 'الزاوية'), y: 'I / I₀' },
    curves: S => [[x => 0.5 * Math.cos(rad(x)) ** 2, T('I = (I₀/2) cos²θ after both', 'I بعد المستقطبين')]],
    draw(p, S, c) { const fr = S.three ? 0.5 * Math.cos(rad(S.th / 2)) ** 4 : 0.5 * Math.cos(rad(S.th)) ** 2; p.dot(S.th, fr, c.pal[3], `${f3(fr * 100)}%`); },
    ro: S => { const fr = S.three ? 0.5 * Math.cos(rad(S.th / 2)) ** 4 : 0.5 * Math.cos(rad(S.th)) ** 2; return [[T('after the first polariser', 'بعد الأول'), f3(S.I0 / 2) + ' W/m²'], [T('transmitted', 'النافذة'), f3(S.I0 * fr) + ' W/m²'], [T('fraction', 'النسبة'), f3(fr * 100) + '%'], [T('Brewster angle tan⁻¹ n', 'زاوية بروستر'), f3(deg(Math.atan(S.n))) + '°']]; },
    st: S => ({ fraction: S.three ? 0.5 * Math.cos(rad(S.th / 2)) ** 4 : 0.5 * Math.cos(rad(S.th)) ** 2, brewsterDeg: deg(Math.atan(S.n)) }),
    intro: S => T(`The first polariser passes half of unpolarised light. The analyser passes the component along its axis: I = I₁cos²θ. At ${S.th}° that is ${f3(100 * 0.5 * Math.cos(rad(S.th)) ** 2)}% of the original. Crossed (90°) polarisers block everything — ${S.three ? 'but a third one between them at 45° lets some light through again, ' + f3(100 * 0.5 * Math.cos(rad(S.th / 2)) ** 4) + '%.' : 'unless you put a third polariser between them (turn it on).'}`, 'قانون مالوس.'),
    ex: () => P('Malus: I = I₀cos²θ;  unpolarised → polariser: I₀/2;  Brewster: reflected light fully polarised when tan θ_B = n (reflected and refracted rays perpendicular).') });

  /* ---------- dual nature, atoms, nuclei ---------- */
  const METAL = { cs: ['Cs', 2.14], k: ['K', 2.30], na: ['Na', 2.36], zn: ['Zn', 4.33], cu: ['Cu', 4.65], pt: ['Pt', 5.65] };
  Y.def({ id: 'photoelectric', kind: K.mod, title: T('The photoelectric effect', 'التأثير الكهروضوئي'), unit: 'JEE Main · Dual nature of matter and radiation', probe: 'light of 400 nm falls on sodium: what is the maximum kinetic energy of the electrons and the stopping potential?',
    rx: /\b(photo ?electric|work function|threshold (frequency|wavelength)|stopping (potential|voltage)|photoelectrons?|einstein'?s? (photoelectric )?equation|photocell|photo ?emission)\b/i, score: 0.96,
    sel: [['metal', T('metal', 'الفلز'), [['na', T('sodium', 'صوديوم'), /sodium|\bNa\b/], ['k', T('potassium', 'بوتاسيوم'), /potassium/i], ['cs', T('caesium', 'سيزيوم'), /c(a)?esium/i], ['zn', T('zinc', 'زنك'), /zinc/i], ['cu', T('copper', 'نحاس'), /copper/i], ['pt', T('platinum', 'بلاتين'), /platinum/i]], 'na']],
    p: [['lam', T('wavelength of the light', 'الطول الموجي'), 'nm', 100, 800, 1, 400, /(\d+(?:\.\d+)?)\s*nm/i], ['I', T('intensity (relative)', 'الشدة'), '', 0, 10, 0.1, 5]],
    view: { x0: 0, x1: 3e15, y0: -6, y1: 8 }, labels: { x: T('frequency f (Hz)', 'التردد'), y: 'KE_max (eV)' },
    draw(p, S, c, H) { const phi = METAL[S.metal][1], f0 = phi * e / h; Object.keys(METAL).forEach((k, i) => { const ph = METAL[k][1], ff = ph * e / h; p.fn(f => (f >= ff ? h * f / e - ph : NaN), k === S.metal ? c.pal[0] : c.muted, { w: k === S.metal ? 2.8 : 1, dash: k === S.metal ? [] : [4, 4] }); }); p.fn(f => h * f / e - phi, c.pal[0], { w: 1, dash: [2, 4] });
      const f = c0 / (S.lam * 1e-9), ke = h * f / e - phi; p.dot(f, Math.max(ke, 0), ke > 0 ? c.pal[3] : c.muted, ke > 0 ? T('your light', 'ضوؤك') : T('below threshold', 'تحت العتبة')); p.dot(f0, 0, c.pal[1], 'f₀'); H.lab(p, 1e14, -5, T(`intercept −φ = −${phi} eV, slope h/e (same for every metal)`, 'الميل h/e'), c.muted); },
    ro: S => { const r = pe(S); return [[T('photon energy hc/λ', 'طاقة الفوتون'), f3(r.E) + ' eV'], [T('work function φ (typical)', 'دالة الشغل'), METAL[S.metal][1] + ' eV'], ['KE_max = hf − φ', r.ke > 0 ? f3(r.ke) + ' eV' : T('no emission', 'لا انبعاث')], [T('stopping potential', 'جهد الإيقاف'), r.ke > 0 ? f3(r.ke) + ' V' : '—'], [T('threshold wavelength hc/φ', 'الطول الموجي الحدي'), f3(r.lam0) + ' nm'], [T('photocurrent', 'التيار'), r.ke > 0 ? T(`∝ intensity (${S.I})`, 'يتناسب مع الشدة') : '0']]; },
    st: S => pe(S),
    intro: S => { const r = pe(S); return r.ke > 0 ? T(`Each ${S.lam} nm photon carries ${f3(r.E)} eV. Freeing an electron from ${METAL[S.metal][0]} costs φ = ${METAL[S.metal][1]} eV, so the fastest electrons leave with ${f3(r.ke)} eV, and a reverse voltage of ${f3(r.ke)} V stops them. Brighter light gives more electrons, not faster ones.`, 'انبعاث.') : T(`A ${S.lam} nm photon (${f3(r.E)} eV) has less energy than the work function (${METAL[S.metal][1]} eV), so no electrons come out however bright the light is — the wavelength must be below ${f3(r.lam0)} nm.`, 'لا انبعاث.'); },
    ex: () => P('hf = φ + KE_max;  eV₀ = KE_max;  f₀ = φ/h, λ₀ = hc/φ;  hc ≈ 1240 eV·nm.  KE_max depends on frequency only; the current on intensity.'), assume: T('Work functions are typical literature values; real surfaces vary with cleanliness and crystal face.', 'قيم نموذجية.') });
  function pe(S) { const E = h * c0 / (S.lam * 1e-9) / e, phi = METAL[S.metal][1]; return { E, ke: E - phi, V0: Math.max(0, E - phi), lam0: h * c0 / (phi * e) * 1e9 }; }

  const PART = { e: ['electron', me, e], p: ['proton', 1.67262192e-27, e], n: ['neutron', 1.67492750e-27, 0], a: ['alpha particle', 6.6446573e-27, 2 * e] };
  Y.def({ id: 'debroglie', kind: K.mod, title: T('de Broglie wavelength of particles', 'طول موجة دي بروي'), unit: 'JEE Main · Dual nature of matter and radiation', probe: 'what is the de Broglie wavelength of an electron accelerated through 100 V?',
    rx: /\b(de ?broglie|matter waves?|wavelength of (an? |the )?(electron|proton|neutron|alpha|particle|ball)|wave[- ]particle duality|davisson|electron diffraction)\b/i, score: 0.96,
    sel: [['pt', T('particle', 'الجسيم'), [['e', T('electron', 'إلكترون'), /electron/i], ['p', T('proton', 'بروتون'), /proton/i], ['n', T('neutron', 'نيوترون'), /neutron/i], ['a', T('alpha particle', 'جسيم ألفا'), /alpha/i]], 'e']],
    p: [['V', T('accelerating voltage (or KE in eV for a neutron)', 'جهد التسريع'), 'V', 1, 100000, 1, 100, /(\d+(?:\.\d+)?)\s*(?:V|volts?|eV)\b/i]],
    auto: true, view: S => ({ x0: 0, x1: 10, y0: -1.5, y1: 1.5 }), grid: false, labels: { x: '', y: '' },
    draw(p, S, c, H) { const r = db(S), nWaves = Math.min(40, Math.max(2, 1e-10 / r.lam * 3)); H.curve(p, x => Math.exp(-((x - 5) ** 2) / 4) * Math.cos(2 * Math.PI * nWaves * x / 10), 0, 10, c.pal[0], { w: 2.2 }, 800); H.lab(p, 0.2, 1.3, T(`wave packet (schematic) · λ = ${f3(r.lam * 1e9)} nm`, 'حزمة موجية'), c.ink); },
    ro: S => { const r = db(S); return [[T('kinetic energy', 'الطاقة الحركية'), f3(r.K / e) + ' eV'], ['p = √(2mK)', f3(r.p) + ' kg·m/s'], ['λ = h/p', f3(r.lam * 1e9) + ' nm = ' + f3(r.lam * 1e10) + ' Å'], ...(S.pt === 'e' ? [[T('shortcut 1.227/√V nm', 'اختصار'), f3(1.227 / Math.sqrt(S.V)) + ' nm']] : [])]; },
    st: S => db(S),
    intro: S => { const r = db(S); return T(`Every moving particle has a wavelength λ = h/p. A ${PART[S.pt][0]} with ${f3(r.K / e)} eV has λ = ${f3(r.lam * 1e9)} nm — comparable to the spacing of atoms in a crystal, which is why electrons diffract (Davisson–Germer). Heavier or faster particles have shorter wavelengths.`, 'طول موجة الجسيم.'); },
    ex: () => P('λ = h/p = h/√(2mK) = h/√(2mqV);  electron: λ ≈ 1.227/√V nm;  a 0.1 kg ball at 10 m/s: λ ≈ 6.6×10⁻³⁴ m (far too small to notice).'), assume: T('Non-relativistic: fine below about 10 kV for electrons.', 'غير نسبي.') });
  function db(S) { const [, m, q] = PART[S.pt], K = (q || e) * S.V, pp = Math.sqrt(2 * m * K); return { K, p: pp, lam: h / pp }; }

  const SERIES = { 1: 'Lyman (UV)', 2: 'Balmer (visible)', 3: 'Paschen (IR)', 4: 'Brackett (IR)', 5: 'Pfund (IR)' }, RY = 13.6057;
  Y.def({ id: 'bohr', kind: K.mod, title: T('Bohr model: energy levels and spectral lines', 'نموذج بور'), unit: 'JEE Main · Atoms and nuclei', probe: 'show the energy levels of hydrogen and the wavelength of the photon emitted from n = 3 to n = 2',
    rx: /\b(bohr'?s? (model|atom|theory|orbits?|radius|postulates?)|hydrogen (spectrum|atom|energy levels?|emission)|energy levels? of (the )?hydrogen|spectral (lines|series)|lyman|balmer|paschen|brackett|pfund|rydberg|electron (jumps?|transition)s?\b.*\b(level|orbit|shell)|ionisation energy of hydrogen)\b/i, score: 0.95,
    p: [['ni', T('from level n_i', 'من المستوى'), '', 2, 8, 1, 3, /from\s*n\s*=\s*(\d+)|n\s*=\s*(\d+)\s*to/i], ['nf', T('to level n_f', 'إلى المستوى'), '', 1, 7, 1, 2, /to\s*n\s*=\s*(\d+)/i], ['Z', T('atomic number Z (hydrogen-like ion)', 'العدد الذري'), '', 1, 5, 1, 1]],
    parse: t => (/\bHe\+|helium ion/i.test(t) ? { Z: 2 } : /\bLi2\+|Li\+\+/i.test(t) ? { Z: 3 } : {}),
    view: { x0: 0, x1: 10, y0: -15, y1: 1.5 }, labels: { x: '', y: 'E (eV)' },
    draw(p, S, c, H) { const En = n => -RY * S.Z * S.Z / (n * n), sc = 1 / (S.Z * S.Z) * 13.6 / 15; for (let n = 1; n <= 8; n++) { const y = En(n) / (S.Z * S.Z); p.path([[0.5, y * 1], [5, y]], n === S.ni || n === S.nf ? c.ink : c.muted, { w: n === S.ni || n === S.nf ? 2.4 : 1.2 }); if (n <= 5 || n === S.ni) H.lab(p, 5.2, y, `n = ${n}: ${f3(En(n))} eV`, c.muted); } void sc;
      p.path([[0.5, 0], [5, 0]], c.muted, { w: 1, dash: [3, 3] }); H.lab(p, 5.2, 0.4, T('ionised (E = 0)', 'متأين'), c.muted);
      if (S.ni > S.nf) { const y1 = En(S.ni) / (S.Z * S.Z), y2 = En(S.nf) / (S.Z * S.Z); p.arrow(2.6, y1, 2.6, y2, c.pal[3], '', { w: 3 }); const lam = 1239.84 / (En(S.ni) - En(S.nf)); H.lab(p, 2.8, (y1 + y2) / 2, `λ = ${f3(lam)} nm`, c.pal[3]); }
      H.circle(p, 8, -7, 0.25, c.pal[1], { w: 1, fill: c.pal[1] }); for (let n = 1; n <= 4; n++) H.circle(p, 8, -7, 0.35 * n * n / 4 + 0.35, n === S.ni || n === S.nf ? c.pal[0] : c.muted, { w: n === S.ni || n === S.nf ? 2 : 0.8 }); H.lab(p, 6.6, -11.6, T('orbits (r ∝ n², not to scale)', 'المدارات'), c.muted); },
    ro: S => { const r = bohr(S); return [[`E_${S.ni}, E_${S.nf}`, `${f3(r.Ei)} eV, ${f3(r.Ef)} eV`], [T('photon energy', 'طاقة الفوتون'), r.dE > 0 ? f3(r.dE) + ' eV' : T('absorbed (n_f > n_i)', 'امتصاص')], [T('wavelength', 'الطول الموجي'), f3(r.lam) + ' nm'], [T('series', 'السلسلة'), SERIES[S.nf] || '—'], [T(`radius of orbit n = ${S.ni}`, 'نصف القطر'), f3(0.529 * S.ni * S.ni / S.Z) + ' Å'], [T('ionisation energy from n = 1', 'طاقة التأين'), f3(RY * S.Z * S.Z) + ' eV']]; },
    st: S => bohr(S),
    intro: S => { const r = bohr(S); return T(`In the Bohr model the electron can only have energies E_n = −13.6 Z²/n² eV. Dropping from n = ${S.ni} to n = ${S.nf} releases the difference, ${f3(Math.abs(r.dE))} eV, as one photon of wavelength ${f3(r.lam)} nm${S.nf === 2 && S.Z === 1 ? ' — a visible Balmer line' : ''}. Lines ending on the same level form a series (${SERIES[S.nf] || ''}).`, 'مستويات الطاقة.'); },
    ex: () => P('E_n = −13.6 Z²/n² eV;  r_n = 0.529 n²/Z Å;  v_n ∝ Z/n;  1/λ = RZ²(1/n_f² − 1/n_i²), R = 1.097×10⁷ m⁻¹;  λ(nm) = 1239.84/ΔE(eV).'), assume: T('Infinite nuclear mass (no reduced-mass correction), so wavelengths differ from measured ones by about 0.05%.', 'كتلة نواة لا نهائية.') });
  function bohr(S) { const Ei = -RY * S.Z * S.Z / (S.ni * S.ni), Ef = -RY * S.Z * S.Z / (S.nf * S.nf), dE = Ei - Ef; return { Ei, Ef, dE, lam: 1239.84 / Math.abs(dE) }; }

  const SEMF = (A, Z) => { const N = A - Z, aV = 15.8, aS = 18.3, aC = 0.714, aA = 23.2, aP = 12; let d = 0; if (Z % 2 === 0 && N % 2 === 0) d = aP / Math.sqrt(A); else if (Z % 2 === 1 && N % 2 === 1) d = -aP / Math.sqrt(A); return aV * A - aS * A ** (2 / 3) - aC * Z * (Z - 1) / A ** (1 / 3) - aA * (A - 2 * Z) ** 2 / A + d; };
  const NUCL = [['²H', 2, 1, 1.112], ['⁴He', 4, 2, 7.074], ['⁶Li', 6, 3, 5.332], ['¹²C', 12, 6, 7.680], ['¹⁶O', 16, 8, 7.976], ['⁵⁶Fe', 56, 26, 8.790], ['⁶²Ni', 62, 28, 8.795], ['¹²⁰Sn', 120, 50, 8.505], ['²⁰⁸Pb', 208, 82, 7.867], ['²³⁵U', 235, 92, 7.591], ['²³⁸U', 238, 92, 7.570]];
  Y.def({ id: 'binding', kind: K.nuc, title: T('Binding energy per nucleon', 'طاقة الربط لكل نيوكليون'), unit: 'JEE Main · Atoms and nuclei', probe: 'show the binding energy per nucleon curve and explain why both fission and fusion release energy',
    rx: /\b(binding energy( per nucleon)?|mass defect|nuclear (fission|fusion) (releases|energy)|why (do )?(both )?(fission and fusion|fusion and fission)|semi[- ]empirical mass formula|nuclear stability|most stable nucleus|why (is )?iron)\b/i, score: 0.95,
    p: [['A', T('mass number A', 'العدد الكتلي'), '', 2, 260, 1, 56]],
    view: { x0: 0, x1: 250, y0: 0, y1: 9.6 }, labels: { x: T('mass number A', 'العدد الكتلي'), y: 'B/A (MeV)' },
    draw(p, S, c, H) { const zs = A => Math.max(1, Math.round(A / (2 + 0.0153 * A ** (2 / 3)))); H.curve(p, A => (A < 5 ? NaN : SEMF(A, zs(A)) / A), 5, 250, c.pal[0], { w: 2.4 }, 400); NUCL.forEach(([nm, A, , b]) => p.dot(A, b, c.pal[3], nm, { r: 3.5 }));
      const A = Math.round(S.A), Z = zs(A); p.dot(A, SEMF(A, Z) / A, c.ink, '', { r: 5 }); H.lab(p, 140, 2.2, T('fusion ← gains | → fission gains', 'اندماج | انشطار'), c.muted); H.lab(p, 140, 1.4, T('dots: measured; line: semi-empirical formula', 'النقاط: مقاسة'), c.muted); },
    ro: S => { const A = Math.round(S.A), Z = Math.max(1, Math.round(A / (2 + 0.0153 * A ** (2 / 3)))), B = SEMF(A, Z); return [[T('most stable Z for this A', 'Z الأكثر استقراراً'), String(Z)], [T('binding energy B (formula)', 'طاقة الربط'), f3(B) + ' MeV'], ['B/A', f3(B / A) + ' MeV']]; },
    st: S => { const A = Math.round(S.A), Z = Math.max(1, Math.round(A / (2 + 0.0153 * A ** (2 / 3)))); return { Z, BA: SEMF(A, Z) / A }; },
    intro: () => T('B/A tells how tightly each nucleon is held. It rises steeply for light nuclei, peaks near iron and nickel (≈ 8.8 MeV), then falls slowly. Moving toward the peak releases energy: joining light nuclei (fusion) or splitting heavy ones (fission). ⁴He sits well above its neighbours — it is unusually stable.', 'منحنى طاقة الربط.'),
    ex: () => P('Mass defect Δm = Zm_p + Nm_n − M;  B = Δm c² (1 u = 931.5 MeV/c²).  Semi-empirical: B = a_VA − a_SA^{2/3} − a_C Z(Z−1)/A^{1/3} − a_A(A − 2Z)²/A ± δ.'), assume: T('Formula coefficients a_V = 15.8, a_S = 18.3, a_C = 0.714, a_A = 23.2, a_P = 12 MeV; it is poor for very light nuclei. Dots are measured values.', 'معاملات الصيغة.') });

  /* ---------- electronic devices ---------- */
  Y.def({ id: 'diode', kind: K.dev, title: T('p–n junction diode: I–V curve and rectifiers', 'الصمام الثنائي'), unit: 'JEE Main · Electronic devices', probe: 'show the I–V characteristic of a silicon diode and how a full-wave rectifier changes AC',
    rx: /\b(p-?n junction|junction diode|diodes?|rectifiers?|half[- ]wave|full[- ]wave|bridge rectifier|forward bias(ed)?|reverse bias(ed)?|zener|i-?v characteristics?|depletion (region|layer)|knee voltage)\b/i, not: /\b(laser|photodiode)\b/i, score: 0.95,
    sel: [['show', T('show', 'اعرض'), [['iv', T('I–V characteristic', 'منحنى التيار والجهد'), /i-?v|characteristic|bias|knee|zener/i], ['half', T('half-wave rectifier output', 'تقويم نصف موجة'), /half[- ]wave/i], ['full', T('full-wave rectifier output', 'تقويم موجة كاملة'), /full[- ]wave|bridge/i]], 'iv']],
    p: [['Is', T('saturation current (log₁₀ A)', 'تيار التشبع'), '', -15, -6, 0.1, -12], ['nI', T('ideality factor n', 'معامل المثالية'), '', 1, 2, 0.05, 1], ['Vz', T('Zener breakdown voltage', 'جهد زينر'), 'V', 2, 20, 0.1, 5.1], ['Vp', T('AC peak voltage (rectifier)', 'ذروة الجهد'), 'V', 1, 30, 0.5, 10], ['Vb', T('test voltage', 'جهد الاختبار'), 'V', -10, 1, 0.01, 0.65]],
    auto: true, view: S => (S.show === 'iv' ? { x0: -S.Vz - 1.5, x1: 1, y0: -0.05, y1: 0.1 } : { x0: 0, x1: 0.06, y0: -S.Vp * 1.2, y1: S.Vp * 1.2 }), labels: { x: '', y: '' },
    draw(p, S, c, H) { const VT = 0.025852, Is = 10 ** S.Is, I = V => (V < -S.Vz ? -(-S.Vz - V) * 0.2 : Is * (Math.exp(Math.min(40, V / (S.nI * VT))) - 1));
      if (S.show === 'iv') { H.curve(p, V => Math.min(0.12, I(V)), p.view.x0, 1, c.pal[0], { w: 2.6 }, 900); p.path([[p.view.x0, 0], [1, 0]], c.muted, { w: 1 }); p.path([[0, -0.05], [0, 0.1]], c.muted, { w: 1 }); H.lab(p, 0.05, 0.095, 'I (A)', c.muted); H.lab(p, 0.6, -0.008, 'V (V)', c.muted); p.dot(S.Vb, Math.min(0.12, I(S.Vb)), c.pal[3], `${f3(S.Vb)} V`); H.lab(p, -S.Vz, -0.03, T('Zener breakdown', 'انهيار زينر'), c.pal[1], { align: 'center' }); return; }
      const w = 2 * Math.PI * 50, vin = t => S.Vp * Math.sin(w * t), out = t => { const v = vin(t), vd = 0.7; return S.show === 'half' ? Math.max(0, v - vd) : Math.max(0, Math.abs(v) - 2 * vd); }; H.curve(p, vin, 0, 0.06, c.muted, { w: 1.4, dash: [5, 4] }, 600); H.curve(p, out, 0, 0.06, c.pal[0], { w: 2.6 }, 600); H.lab(p, 0.001, S.Vp * 1.1, T('dashed: input AC (50 Hz) · solid: output across the load', 'المتقطع: الدخل'), c.muted); },
    ro: S => { const VT = 0.025852, Is = 10 ** S.Is, I = Is * (Math.exp(Math.min(40, S.Vb / (S.nI * VT))) - 1); return S.show === 'iv' ? [[T('current at the test voltage', 'التيار'), S.Vb < -S.Vz ? T('breakdown', 'انهيار') : f3(I) + ' A'], [T('thermal voltage kT/q (300 K)', 'الجهد الحراري'), f3(VT * 1e3) + ' mV'], [T('dynamic resistance nV_T/I', 'المقاومة الديناميكية'), I > 0 ? f3(S.nI * VT / I) + ' Ω' : '—']] : [[T('output peak', 'ذروة الخرج'), f3(S.show === 'half' ? S.Vp - 0.7 : S.Vp - 1.4) + ' V'], [T('output frequency', 'تردد الخرج'), S.show === 'half' ? '50 Hz' : '100 Hz'], [T('average (DC) output ≈', 'المتوسط'), f3((S.show === 'half' ? 1 / Math.PI : 2 / Math.PI) * (S.Vp - (S.show === 'half' ? 0.7 : 1.4))) + ' V']]; },
    st: S => { const VT = 0.025852, Is = 10 ** S.Is; return { I: Is * (Math.exp(Math.min(40, S.Vb / (S.nI * VT))) - 1), outPeak: S.show === 'half' ? S.Vp - 0.7 : S.Vp - 1.4 }; },
    intro: S => (S.show === 'iv' ? T('Forward-biased, almost no current flows until about 0.6–0.7 V for silicon, then it rises exponentially (I = I_s(e^{V/nV_T} − 1)). Reverse-biased only a tiny saturation current leaks — until breakdown, which a Zener diode uses to hold a steady voltage.', 'منحنى الصمام.') : T(`A diode lets current through in one direction only. A half-wave rectifier keeps the positive halves; a full-wave (bridge) rectifier flips the negative halves up too, so the output pulses at twice the frequency. Each silicon diode in the path drops about 0.7 V.`, 'التقويم.')),
    ex: () => P('Shockley: I = I_s(e^{V/(nV_T)} − 1), V_T = kT/q ≈ 25.9 mV at 300 K.  Half-wave: V_dc ≈ V_m/π, ripple frequency f;  full-wave: V_dc ≈ 2V_m/π, ripple 2f.'), assume: T('Ideal diode model with a fixed 0.7 V drop for the rectifier view; I–V uses the Shockley equation plus a simple linear breakdown.', 'نموذج مبسط.') });

  const GATES = { and: ['AND', (a, b) => a && b], or: ['OR', (a, b) => a || b], not: ['NOT', a => !a], nand: ['NAND', (a, b) => !(a && b)], nor: ['NOR', (a, b) => !(a || b)], xor: ['XOR', (a, b) => a !== b], xnor: ['XNOR', (a, b) => a === b] };
  Y.def({ id: 'logic', kind: K.dev, title: T('Logic gates and truth tables', 'البوابات المنطقية'), unit: 'JEE Main · Electronic devices (logic gates)', probe: 'show the truth table of a NAND gate and why it is called a universal gate',
    rx: /\b(logic gates?|truth tables?|nand( gate)?|nor gate|xor( gate)?|xnor|and gate|or gate|not gate|boolean (algebra|logic|expressions?)|universal gates?)\b/i, score: 0.95,
    sel: [['g', T('gate', 'البوابة'), Object.keys(GATES).map(k => [k, GATES[k][0], new RegExp('\\b' + GATES[k][0] + '\\b', 'i')]), 'nand']], tog: [['A', T('input A', 'المدخل A'), true], ['B', T('input B', 'المدخل B'), false]],
    view: { x0: 0, x1: 12, y0: 0, y1: 7 }, grid: false, labels: { x: '', y: '' },
    draw(p, S, c, H) { const G = GATES[S.g], one = S.g === 'not', out = one ? G[1](S.A) : G[1](S.A, S.B); const on = v => (v ? c.pal[2] : c.muted);
      p.path([[0.5, 5], [2.5, 5]], on(S.A), { w: 4 }); H.lab(p, 0.3, 5.4, `A = ${S.A ? 1 : 0}`, on(S.A)); if (!one) { p.path([[0.5, 3], [2.5, 3]], on(S.B), { w: 4 }); H.lab(p, 0.3, 3.4, `B = ${S.B ? 1 : 0}`, on(S.B)); }
      H.poly(p, [[2.5, 2.2], [4.5, 2.2], [5.4, 4], [4.5, 5.8], [2.5, 5.8]], c.ink, { w: 2, fill: 'rgba(37,99,235,.08)' }); H.lab(p, 3.95, 4, G[0], c.ink, { align: 'center', font: '700 15px ui-sans-serif' }); p.path([[5.4, 4], [7, 4]], on(out), { w: 4 }); H.lab(p, 6.2, 4.4, `Y = ${out ? 1 : 0}`, on(out));
      const rows = one ? [[0], [1]] : [[0, 0], [0, 1], [1, 0], [1, 1]]; H.lab(p, 8, 6.4, one ? 'A | Y' : 'A B | Y', c.ink, { font: '700 13px ui-monospace, monospace' }); rows.forEach((r, i) => { const y = one ? G[1](!!r[0]) : G[1](!!r[0], !!r[1]), cur = one ? !!r[0] === S.A : !!r[0] === S.A && !!r[1] === S.B; H.lab(p, 8, 5.6 - i * 0.8, `${r.join(' ')} | ${y ? 1 : 0}`, cur ? c.pal[3] : c.ink, { font: (cur ? '700 ' : '') + '13px ui-monospace, monospace' }); }); },
    ro: S => { const G = GATES[S.g]; return [[T('output Y', 'الخرج'), String(+(S.g === 'not' ? G[1](S.A) : G[1](S.A, S.B)))], [T('Boolean expression', 'التعبير'), { and: 'Y = A·B', or: 'Y = A + B', not: 'Y = Ā', nand: 'Y = (A·B)‾', nor: 'Y = (A + B)‾', xor: 'Y = A⊕B = AB̄ + ĀB', xnor: 'Y = (A⊕B)‾' }[S.g]]]; },
    st: S => { const G = GATES[S.g]; return { Y: +(S.g === 'not' ? G[1](S.A) : G[1](S.A, S.B)), table: S.g === 'not' ? [0, 1].map(a => +G[1](!!a)) : [[0, 0], [0, 1], [1, 0], [1, 1]].map(([a, b]) => +G[1](!!a, !!b)) }; },
    intro: S => (S.g === 'nand' || S.g === 'nor' ? T(`${GATES[S.g][0]} is a universal gate: NOT, AND and OR can all be built from it alone (e.g. NOT A = A ${GATES[S.g][0]} A). Toggle A and B — the highlighted row of the truth table is the current input.`, 'بوابة عامة.') : T(`Toggle the inputs: the output follows the ${GATES[S.g][0]} rule shown in the truth table.`, 'جدول الحقيقة.')),
    ex: () => P('De Morgan: (A·B)‾ = Ā + B̄, (A + B)‾ = Ā·B̄.  From NAND: NOT A = (A·A)‾;  A·B = ((A·B)‾)‾;  A + B = (Ā·B̄)‾.') });

  /* ---------- undergraduate modern physics ---------- */
  Y.def({ id: 'relativity', kind: K.adv, title: T('Special relativity: time dilation and length contraction', 'النسبية الخاصة'), unit: 'Undergraduate · Special relativity', probe: 'how much does time slow down for a spaceship moving at 0.8c, and why do muons reach the ground?',
    rx: /\b(special relativity|relativity\b.*\b(time|length|speed)|time dilation|length contraction|lorentz (factor|transformation|contraction)|relativistic (mass|momentum|energy|speed)|twin paradox|muons? (reach|reaching|lifetime|decay)|e\s*=\s*mc\s*\^?\s*2)\b/i, score: 0.95,
    p: [['b', T('speed v/c', 'السرعة v/c'), '', 0, 0.999, 0.001, 0.8, /(0?\.\d+)\s*c\b/i], ['t0', T('proper time (moving clock)', 'الزمن الذاتي'), 's', 0.1, 100, 0.1, 1], ['L0', T('proper length', 'الطول الذاتي'), 'm', 1, 1000, 1, 100]],
    parse: t => (/\bmuon/i.test(t) ? { b: 0.995, t0: 2.2 } : {}),
    view: { x0: 0, x1: 1, y0: 0, y1: 12 }, labels: { x: 'v / c', y: 'γ' },
    draw(p, S, c, H) { H.curve(p, b => 1 / Math.sqrt(1 - b * b), 0, 0.996, c.pal[0], { w: 2.6 }, 500); const gm = 1 / Math.sqrt(1 - S.b * S.b); p.dot(S.b, Math.min(12, gm), c.pal[3], `γ = ${f3(gm)}`); H.lab(p, 0.03, 11, T('γ = 1/√(1 − v²/c²) — almost 1 until v is a sizeable fraction of c', 'عامل لورنتز'), c.muted); },
    ro: S => { const gm = 1 / Math.sqrt(1 - S.b * S.b); return [['γ', f3(gm)], [T('dilated time γΔt₀', 'الزمن المتمدد'), f3(gm * S.t0) + ' s'], [T('contracted length L₀/γ', 'الطول المنكمش'), f3(S.L0 / gm) + ' m'], [T('KE per kg (γ − 1)c²', 'الطاقة الحركية لكل كغ'), f3((gm - 1) * c0 * c0) + ' J']]; },
    st: S => { const gm = 1 / Math.sqrt(1 - S.b * S.b); return { gamma: gm, dilated: gm * S.t0, contracted: S.L0 / gm }; },
    intro: S => { const gm = 1 / Math.sqrt(1 - S.b * S.b); return T(`At ${S.b}c, γ = ${f3(gm)}: a clock on the ship ticks ${f3(gm)} times slower as seen from Earth, and the ship is ${f3(gm)} times shorter along its motion. Muons made high in the atmosphere live only 2.2 µs at rest, but at 0.995c (γ ≈ 10) they live long enough to reach the ground.`, 'تمدد الزمن.'); },
    ex: () => P('Δt = γΔt₀;  L = L₀/γ;  p = γmv;  E = γmc², KE = (γ − 1)mc²;  E² = (pc)² + (mc²)²;  velocity addition u′ = (u − v)/(1 − uv/c²).') });

  Y.def({ id: 'qmbox', kind: K.adv, title: T('Particle in a box (infinite square well)', 'جسيم في صندوق'), unit: 'Undergraduate · Quantum mechanics', probe: 'show the wavefunctions and energy levels of an electron in a 1 nm box',
    rx: /\b(particle in a (1d |one[- ]dimensional )?box|infinite (square |potential )?well|schr[oö]dinger('?s)? equation|wave ?functions?|probability density|quantum (well|confinement|numbers? in a box)|zero[- ]point energy)\b/i, not: /\b(hydrogen|orbital|atom)\b/i, score: 0.95,
    p: [['n', T('quantum number n', 'العدد الكمي'), '', 1, 10, 1, 2], ['Lnm', T('box width', 'عرض الصندوق'), 'nm', 0.1, 10, 0.05, 1, /(\d+(?:\.\d+)?)\s*nm\s*(?:wide|box|well)/i], ['x1', T('probability from x₁ (fraction of L)', 'من x₁'), '', 0, 1, 0.01, 0], ['x2', T('to x₂', 'إلى x₂'), '', 0, 1, 0.01, 0.25]],
    view: { x0: -0.1, x1: 1.1, y0: -1.8, y1: 2.4 }, labels: { x: 'x / L', y: '' },
    draw(p, S, c, H) { p.path([[0, -1.8], [0, 2.4]], c.ink, { w: 3 }); p.path([[1, -1.8], [1, 2.4]], c.ink, { w: 3 }); const psi = x => Math.SQRT2 * Math.sin(S.n * Math.PI * x);
      H.shade(p, x => psi(x) ** 2 / 2, null, Math.min(S.x1, S.x2), Math.max(S.x1, S.x2), 'rgba(217,119,6,.35)'); H.curve(p, psi, 0, 1, c.pal[0], { w: 2.2 }); H.curve(p, x => psi(x) ** 2 / 2, 0, 1, c.pal[3], { w: 2 }); H.lab(p, 0.02, 2.2, T('blue: ψ(x) · orange: |ψ|² (scaled)', 'ψ و |ψ|²'), c.muted); },
    ro: S => { const r = box(S); return [['Eₙ = n²h²/(8mL²)', f3(r.E) + ' eV'], [T('ground state E₁', 'الحالة الأرضية'), f3(r.E1) + ' eV'], [T('nodes inside', 'العقد'), String(S.n - 1)], [T('P(x₁ < x < x₂)', 'الاحتمال'), f3(r.prob)], [T(`photon for n → n − 1`, 'فوتون'), S.n > 1 ? f3(1239.84 / (r.E - r.E1 * (S.n - 1) ** 2)) + ' nm' : '—']]; },
    st: S => box(S),
    intro: S => T(`An electron trapped between infinitely high walls can only fit whole numbers of half-wavelengths: ψₙ = √(2/L) sin(nπx/L). So its energy is quantised, Eₙ ∝ n², with ${S.n - 1} node${S.n === 2 ? '' : 's'} inside for n = ${S.n}. |ψ|² is where you are likely to find it; the shaded area is the probability between x₁ and x₂.`, 'التكميم.'),
    ex: () => P('ψₙ(x) = √(2/L) sin(nπx/L), 0 < x < L;  Eₙ = n²π²ħ²/(2mL²) = n²h²/(8mL²);  ∫|ψ|² dx = 1;  P(a < x < b) = ∫ₐᵇ |ψ|² dx.') });
  function box(S) { const L0 = S.Lnm * 1e-9, E1 = h * h / (8 * me * L0 * L0) / e, a = Math.min(S.x1, S.x2), b = Math.max(S.x1, S.x2), k = S.n * Math.PI; const prob = (b - a) - (Math.sin(2 * k * b) - Math.sin(2 * k * a)) / (2 * k); return { E: E1 * S.n * S.n, E1, prob }; }

  Y.def({ id: 'blackbody', kind: K.adv, title: T('Black-body radiation (Planck, Wien, Stefan)', 'إشعاع الجسم الأسود'), unit: 'JEE Main (Wien, Stefan) / Undergraduate · Thermal radiation', probe: 'show the black-body spectrum of the Sun at 5772 K and where it peaks',
    rx: /\b(black[- ]?body|planck'?s? (law|radiation|distribution)|wien'?s? (law|displacement)|stefan(['’]s)?[- ]?(boltzmann)?( law)?|thermal radiation|ultraviolet catastrophe|why (do )?hot objects glow|colour of (a )?(star|hot object))\b/i, score: 0.95,
    p: [['T', T('temperature', 'درجة الحرارة'), 'K', 300, 12000, 10, 5772, /(\d{3,5})\s*K\b/i], ['T2', T('compare with', 'قارن مع'), 'K', 0, 12000, 10, 3000]],
    parse: t => (/\bsun\b/i.test(t) ? { T: 5772 } : /\b(human|body temperature)\b/i.test(t) ? { T: 310, T2: 0 } : {}),
    auto: true, view: S => { const lm = 2.897771955e-3 / Math.max(S.T, S.T2 || 0); const B = planck(lm, Math.max(S.T, S.T2)); return { x0: 0, x1: Math.min(30000, lm * 1e9 * 5), y0: 0, y1: B * 1.15 }; }, labels: { x: 'λ (nm)', y: T('spectral radiance', 'الإشعاع الطيفي') },
    draw(p, S, c, H) { const vis = [[380, 'rgba(120,0,200,.12)'], [450, 'rgba(0,0,255,.12)'], [495, 'rgba(0,180,0,.12)'], [570, 'rgba(230,200,0,.15)'], [590, 'rgba(255,120,0,.15)'], [620, 'rgba(255,0,0,.12)'], [750, null]]; for (let i = 0; i < vis.length - 1; i++) p.path([[vis[i][0], 0], [vis[i + 1][0], 0], [vis[i + 1][0], p.view.y1], [vis[i][0], p.view.y1]], vis[i][1], { w: 0, close: true, fill: vis[i][1] });
      [S.T, S.T2].forEach((Tq, i) => { if (!Tq) return; H.curve(p, l => planck(l * 1e-9, Tq), 1, p.view.x1, c.pal[i], { w: 2.6 }, 600); const lm = 2.897771955e-3 / Tq * 1e9; p.dot(lm, planck(lm * 1e-9, Tq), c.pal[i], `${Tq} K: λ_max = ${f3(lm)} nm`); }); },
    ro: S => { const lm = 2.897771955e-3 / S.T; return [[T('Wien peak b/T', 'ذروة فين'), f3(lm * 1e9) + ' nm'], [T('Stefan power per area σT⁴', 'القدرة لكل وحدة مساحة'), f3(5.670374419e-8 * S.T ** 4) + ' W/m²'], ...(S.T2 ? [[T('power ratio (T/T₂)⁴', 'نسبة القدرة'), f3((S.T / S.T2) ** 4)]] : [])]; },
    st: S => ({ lmax: 2.897771955e-3 / S.T, power: 5.670374419e-8 * S.T ** 4 }),
    intro: S => T(`Every object glows with a spectrum set only by its temperature. At ${S.T} K it peaks at λ_max = b/T = ${f3(2.897771955e-3 / S.T * 1e9)} nm (Wien), and radiates σT⁴ = ${f3(5.670374419e-8 * S.T ** 4)} W per m² (Stefan) — doubling T multiplies the power by 16. Planck explained the shape by assuming energy comes in quanta hf.`, 'إشعاع الجسم الأسود.'),
    ex: () => P('Planck: B(λ, T) = (2hc²/λ⁵)/(e^{hc/λkT} − 1);  Wien: λ_max T = 2.898×10⁻³ m·K;  Stefan: P = σAT⁴ (εσAT⁴ for a grey body), σ = 5.67×10⁻⁸ W m⁻² K⁻⁴.') });
  function planck(l, Tq) { const x = h * c0 / (l * kB * Tq); return x > 700 ? 0 : 2 * h * c0 * c0 / l ** 5 / (Math.exp(x) - 1); }

  /* ---------- experimental skills ---------- */
  Y.def({ id: 'vernier', kind: K.exp, title: T('Reading a vernier caliper', 'قراءة الورنية'), unit: 'JEE Main · Experimental skills', probe: 'how do I read a vernier caliper with least count 0.1 mm and correct a zero error?',
    rx: /\b(vernier( caliper| callipers?| scale)?|screw gauge|least count|zero error|micrometer( screw)?|main scale reading)\b/i, score: 0.96,
    p: [['L', T('true length of the object', 'الطول الحقيقي'), 'mm', 0, 60, 0.01, 23.47], ['z', T('zero error', 'خطأ الصفر'), 'mm', -0.5, 0.5, 0.1, 0]],
    view: { x0: 10, x1: 45, y0: -3, y1: 4 }, grid: false, labels: { x: 'mm', y: '' },
    draw(p, S, c, H) { const LC = 0.1, pos = S.L + S.z; for (let mm = 10; mm <= 45; mm++) { p.path([[mm, 0], [mm, mm % 10 === 0 ? 1.4 : mm % 5 === 0 ? 1 : 0.7]], c.ink, { w: 1.2 }); if (mm % 10 === 0) H.lab(p, mm, 1.8, String(mm / 10), c.ink, { align: 'center' }); }
      const coin = Math.round(((pos * 10) % 10 + 10) % 10) % 10; for (let k = 0; k <= 10; k++) { const x = pos + k * 0.9; p.path([[x, 0], [x, -(k % 5 === 0 ? 1.2 : 0.8)]], k === coin ? c.pal[3] : c.pal[0], { w: k === coin ? 2.6 : 1.2 }); if (k % 5 === 0) H.lab(p, x, -1.7, String(k), c.pal[0], { align: 'center' }); }
      p.path([[pos, 0.2], [pos, -2.4]], c.pal[2], { w: 1, dash: [3, 3] }); H.lab(p, pos, -2.8, T('vernier zero', 'صفر الورنية'), c.pal[2], { align: 'center' }); void LC; },
    ro: S => { const pos = S.L + S.z, msr = Math.floor(pos + 1e-9), vsd = Math.round((pos - msr) / 0.1) % 10, obs = msr + vsd * 0.1; return [[T('least count = 1 MSD − 1 VSD', 'أصغر قراءة'), '1 mm − 0.9 mm = 0.1 mm'], [T('main scale reading', 'قراءة المقياس الرئيسي'), msr + ' mm'], [T('coinciding vernier division', 'التدريج المنطبق'), String(vsd)], [T('observed reading', 'القراءة المرصودة'), f3(obs) + ' mm'], [T('corrected = observed − zero error', 'المصححة'), f3(obs - S.z) + ' mm']]; },
    st: S => { const pos = S.L + S.z, msr = Math.floor(pos + 1e-9), vsd = Math.round((pos - msr) / 0.1) % 10, obs = msr + vsd * 0.1; return { observed: +obs.toFixed(2), corrected: +(obs - S.z).toFixed(2) }; },
    intro: () => T('Ten vernier divisions span nine main-scale millimetres, so each is 0.1 mm shorter: the least count. Read the main scale just before the vernier zero, then find which vernier mark lines up exactly with a main-scale mark (highlighted) and add that many tenths. Subtract any zero error (positive if the zero sits to the right when the jaws are closed).', 'قراءة الورنية.'),
    ex: () => P('Reading = MSR + (coinciding VSD × LC) − zero error;  LC = 1 MSD − 1 VSD = MSD/n.  Screw gauge: LC = pitch / number of circular divisions.') });
})();
